/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A51 staging · exact frozen manifest impede–impulsive (80 lemmas). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[c],mistakes:[m],quiz:qs});
P('impede','impede 源自拉丁语 impedire，含有“缠住脚步、阻碍”的历史义，现代指拖慢进展。',C('impede.s1','交通管理','A broken signal impeded traffic on the bridge, so crews directed cars through one open lane.','信号灯故障妨碍了桥上交通，因此工作人员引导车辆从一条开放车道通行。','A broken signal impeded traffic / on the bridge / so crews directed cars / through one open lane.','impede 是及物动词，直接接受影响的事物 traffic；so 引出应对措施。','信号故障使通行进展变慢，符合 s1。'),M('The broken signal impeded traffic by making every car move faster and clearing the bridge immediately.','The broken signal improved traffic flow by clearing the bridge immediately.','使车辆更快通过并清空桥面不是“拖慢进展”。'),[Q('impede',1,1,'To impede progress is to?','slow it down','make it certain','describe it humorously','impede 指妨碍、拖慢进展。'),Q('impede',2,1,'Which event could impede a rescue?','a blocked road','a clear route','extra emergency staff','道路受阻会妨碍救援。'),Q('impede',3,1,'In “Rain impeded the search,” rain?','made the search harder or slower','completed the search','was searched for','impede 后接被阻碍的对象。'),Q('impede',4,1,'A close synonym for impede is?','hinder','accelerate','admire','hinder 同样表示阻碍。')]);
P('impediment','impediment 由 impede 相关词形发展而来，指拖慢行动的困难，也可专指言语障碍。',C('impediment.s1','项目规划','Limited laboratory space was an impediment to the study, so the team scheduled the experiments in shifts.','实验室空间有限是这项研究的一大障碍，因此团队分时段安排实验。','Limited laboratory space / was an impediment to the study / so the team scheduled the experiments / in shifts.','impediment 常用 an impediment to 表示对某事的障碍；so 引出解决安排。','空间限制拖慢了研究安排，符合 s1。'),M('The report called the extra laboratory space an impediment even though it allowed every experiment to proceed sooner.','The report called the lack of laboratory space an impediment because it delayed the experiments.','额外空间使工作更快，不是妨碍。'),[Q('impediment',1,1,'An impediment to progress is?','a difficulty that slows it','a guarantee of success','a final result','impediment 指拖慢进展的困难。'),Q('impediment',2,2,'A speech impediment is a difficulty with?','speaking clearly','hearing music','walking through a forest','s2 特指说话清晰度方面的困难。'),Q('impediment',3,1,'Which phrase is natural?','an impediment to research','an impediment of a joke','an impediment under a color','常见搭配是 impediment to。'),Q('impediment',4,1,'If funding is an impediment, it?','gets in the way of the work','makes the work unnecessary','proves the results','障碍会妨碍工作进行。')]);
P('impel','impel 源自拉丁语 impellere（推动），表示某种力量或感受驱使某人采取行动。',C('impel.s1','志愿服务','A strong sense of fairness impelled Jo to speak up when the quiet intern was blamed for someone else’s error.','强烈的公平感驱使乔在安静的实习生被错怪时站出来说话。','A strong sense of fairness impelled Jo / to speak up / when the quiet intern was blamed / for someone else’s error.','impel 常用 impel someone to do，表示驱使某人做某事；when 从句交代行动缘由。','公平感推动乔采取行动，符合 s1。'),M('A sense of fairness impelled Jo to remain silent and let an innocent colleague take the blame.','A sense of fairness held Jo back from speaking up for the innocent colleague.','为公平而保持沉默、任无辜者被责备，与该例中“驱使行动”的意思不符。'),[Q('impel',1,1,'To impel someone to act is to?','drive or urge them to act','prevent every action','describe their appearance','impel 表示驱使某人行动。'),Q('impel',2,1,'Which construction is standard?','impel someone to speak','impel someone speaking at','impel someone for speak','常用结构是 impel someone to do。'),Q('impel',3,1,'A strong feeling may impel a person by?','pushing them toward an action','making the feeling disappear','turning it into a place','情感可以成为行动的驱动力。'),Q('impel',4,1,'In the sentence, what impelled Jo?','her sense of fairness','the intern’s error','the laboratory schedule','主语 sense of fairness 是驱使乔的力量。')]);
P('impend','impend 源自拉丁语 impendere，有“悬在上方、即将来临”之意，现常描述威胁迫近。',C('impend.s1','天气预警','Dark clouds impended over the coastal village, and the harbor master advised boats to return before dusk.','乌云笼罩着海滨村庄、暴风雨似乎即将来临，港口负责人建议船只在黄昏前返航。','Dark clouds impended over the coastal village / and the harbor master advised boats / to return before dusk.','impend 可与 over 连用表示危险逼近；and 连接天候迹象与安全建议。','风暴威胁似乎即将到来，符合 s1；此动词较少见，impending 更常用。'),M('A danger impended over the village although every warning said the threat had passed weeks ago.','A danger had passed the village, so no threat impended.','威胁已消失数周，不能说仍迫近。'),[Q('impend',1,1,'If danger impends, it?','is about to happen','has been forgotten forever','has already been carefully solved','impend 指危险迫近。'),Q('impend',2,1,'Which word is more common in everyday use?','impending','impend','impendment','描述即将发生时 impending 更常见。'),Q('impend',3,1,'“A storm impends over the coast” means the storm?','is drawing near','has safely moved away','is being measured indoors','impend over 表示即将逼近。'),Q('impend',4,1,'An impending danger is?','a danger that may soon arrive','a danger that ended long ago','a harmless joke','impend 与即将到来的危险有关。')]);
P('impending','impending 是由 impend 发展而来的形容词，表示很快就要发生的。',C('impending.s1','校园通知','Students moved their outdoor presentation indoors because of the impending storm forecast for late afternoon.','由于预报傍晚将有暴风雨，学生们把户外展示改到了室内。','Students moved their outdoor presentation indoors / because of the impending storm / forecast for late afternoon.','impending 修饰 storm，表示即将来临；because of 引出更换场地的原因。','暴风雨预计很快到来，符合 s1。'),M('They prepared for the impending storm after the forecast confirmed that it had ended the previous day.','They prepared for a possible future storm after the forecast warned it was approaching.','已经结束的风暴不能称为 impending。'),[Q('impending',1,1,'An impending event is?','about to happen soon','impossible to understand','already finished long ago','impending 表示即将发生的。'),Q('impending',2,1,'Which phrase is natural?','an impending deadline','an impending yesterday','an impending already-completed event','impending 修饰未来临近的事件。'),Q('impending',3,1,'Why move a presentation indoors for an impending storm?','the storm is expected soon','the storm has disappeared','the room is more distant','即将到来的风暴会影响户外活动。'),Q('impending',4,1,'A close synonym for impending is?','imminent','permanent','impermeable','imminent 同样表示即将来临。')]);
P('impenetrable','impenetrable 由否定前缀 im-、penetrate 与 -able 构成，可指无法穿过或难以理解。',C('impenetrable.s2','专业写作','The manual was so impenetrable that new volunteers could not understand the safety procedure without a trainer’s help.','这本手册晦涩难懂，新志愿者没有培训员帮助就无法理解安全流程。','The manual was so impenetrable / that new volunteers could not understand the safety procedure / without a trainer’s help.','impenetrable 在此表示难以理解；so ... that 表示程度导致的结果。','新手无法看懂手册，符合 s2。'),M('The guide called the manual impenetrable even though every new volunteer understood it immediately without help.','The guide called the manual clear because every new volunteer understood it immediately.','人人都能立即理解的文本并非难以理解。'),[Q('impenetrable',1,1,'An impenetrable forest is one that?','is too dense to pass through','is easy to walk across','has no trees','s1 指无法穿过的。'),Q('impenetrable',2,2,'Impenetrable jargon is?','impossible or very hard to understand','simple for every reader','a kind of rainfall','s2 指难以理解。'),Q('impenetrable',3,1,'A barrier described as impenetrable?','blocks passage through it','opens automatically for everyone','is only a written explanation','该词的字面义是无法穿透。'),Q('impenetrable',4,2,'If a manual is impenetrable to beginners, they?','cannot make sense of it','can follow it easily','have already memorized it','这里强调内容难懂。')]);
P('imperative','imperative 源自拉丁语 imperare（命令），可表示紧急必要、命令式、必须做的事或祈使语气。',C('imperative.s1','公共安全','It is imperative that every visitor leave the building by the marked exit during the alarm.','警报响起时，每位访客都必须从标示的出口离开大楼。','It is imperative / that every visitor leave the building / by the marked exit / during the alarm.','It is imperative that 后常用动词原形 leave，表达迫切必要。','警报期间疏散十分紧要，符合 s1。'),M('The notice said it was imperative to ignore the alarm and remain inside during evacuation.','The notice said it was imperative to follow the alarm and leave by the exit.','警报疏散时留在楼内会违背迫切的安全要求。'),[Q('imperative',1,1,'If action is imperative, it is?','extremely important and urgent','optional and unimportant','already impossible','s1 表示紧急而必要。'),Q('imperative',2,2,'An imperative tone sounds?','like an order','uncertain and apologetic','unrelated to the topic','s2 是命令式或带权威的口吻。'),Q('imperative',3,3,'A moral imperative is?','something that must be done','a casual suggestion','a kind of tense','imperative 作名词可指必须做的事。'),Q('imperative',4,4,'“Close the door” uses which grammatical form?','the imperative','the imperfect','the passive only','直接命令动词使用祈使语气。')]);
P('imperceptibly','imperceptibly 是 imperceptible 的副词，表示变化微小或缓慢到几乎察觉不到。',C('imperceptibly.s1','光线变化','As the sun set behind the hills, the room darkened imperceptibly until the lamps seemed unusually bright.','太阳落到山后时，房间不知不觉地暗下来，直到灯光显得格外明亮。','As the sun set behind the hills / the room darkened imperceptibly / until the lamps seemed unusually bright.','imperceptibly 修饰 darkened，说明变化难以察觉；until 标示变化达到的结果。','光线是逐渐而微弱地变暗，符合 s1。'),M('The room darkened imperceptibly in a sudden flash that everyone noticed at once.','The room darkened abruptly in a sudden flash that everyone noticed at once.','所有人立刻察觉的突然变化不是 imperceptible。'),[Q('imperceptibly',1,1,'Imperceptibly means?','so slightly or gradually that it is hard to notice','in a loud and obvious way','with certainty and force','imperceptibly 表示不易察觉地。'),Q('imperceptibly',2,1,'If a color changes imperceptibly, the change is?','too small to notice easily','dramatic and immediate','completely absent','该副词强调细微到难察觉。'),Q('imperceptibly',3,1,'Which sentence fits imperceptibly?','The light faded so gradually that no one noticed.','The alarm flashed brightly all at once.','The room became darker in one obvious instant.','缓慢细微的变化符合 imperceptibly。'),Q('imperceptibly',4,1,'The adjective form is?','imperceptible','imperative','imperialism','imperceptibly 由 imperceptible 派生。')]);
P('imperfect','imperfect 可表示有缺陷或不完整，也可作名词指某些语言中表示过去持续或习惯动作的未完成体。',C('imperfect.s1','数据审核','The first survey was imperfect because several rural households had been left out of the sample.','第一轮调查并不完整，因为样本漏掉了几户农村家庭。','The first survey was imperfect / because several rural households / had been left out / of the sample.','imperfect 在此表示不完整、有缺漏；because 说明调查不完善的原因。','抽样漏掉一部分家庭，符合 s1。'),M('The survey was called imperfect even though it included every household and contained no identified gaps.','The survey was called complete because it included every household and contained no identified gaps.','没有缺漏的调查不符合“不完整”的描述。'),[Q('imperfect',1,1,'An imperfect plan may?','contain faults or be incomplete','have no possible flaw','be a kind of command','imperfect 表示有缺陷或不完整。'),Q('imperfect',2,2,'In grammar, the imperfect may describe?','ongoing or habitual past action','a command to act now','a future event only','语法义表示过去持续或习惯动作。'),Q('imperfect',3,1,'A sample that leaves out rural households is?','imperfect','impenetrable','imperial','漏掉群体会使样本不完整。'),Q('imperfect',4,2,'The imperfect is a term used in?','grammar','weather forecasting only','construction materials','该术语指语法体或时态。')]);
P('imperial','imperial 源自拉丁语 imperium（统治、帝国），可指帝国或皇帝相关、威严专横，也可指英制。',C('imperial.s1','历史建筑','The guide explained how the imperial palace served as the ruler’s official residence and administrative center.','导览员介绍了皇宫如何作为统治者的正式住所和行政中心。','The guide explained / how the imperial palace served / as the ruler’s official residence / and administrative center.','imperial 修饰 palace，表示与帝国统治者相关；how 从句说明其用途。','宫殿与统治者及帝国行政相关，符合 s1。'),M('The guide called a small village bakery an imperial palace even though it had no connection to an empire or ruler.','The guide called the ruler’s official residence an imperial palace.','普通面包店与帝国或统治者无关。'),[Q('imperial',1,1,'An imperial palace is connected with?','an empire or its ruler','a farm tool','a speech difficulty','imperial 的 s1 与帝国或皇帝有关。'),Q('imperial',2,2,'An imperial manner may seem?','majestic or domineering','quietly apologetic','impossible to pass through','s2 指威严或专横的风格。'),Q('imperial',3,3,'Imperial measurements belong to?','the British system of weights and measures','a system of religious songs','a type of water cycle','s3 指英制度量衡。'),Q('imperial',4,1,'Which phrase uses the empire-related sense?','imperial administration','imperial pint','an imperial and domineering tone','imperial administration 属帝国治理语境。')]);
P('imperialism','imperialism 由 imperial 加 -ism 构成，指对其他国家施加统治或强大影响、常为获取资源的政策。',C('imperialism.s1','历史讨论','The lecture examines how imperialism reshaped borders and economies in several regions during the nineteenth century.','讲座探讨了十九世纪帝国主义如何重塑多个地区的边界和经济。','The lecture examines / how imperialism reshaped borders and economies / in several regions / during the nineteenth century.','imperialism 是历史政治概念；how 引出其造成的影响。','讨论跨国统治与影响力，符合 s1。'),M('The essay defined imperialism as two independent countries having no political influence over one another.','The essay defined imperialism as one country ruling or strongly influencing another.','彼此毫无影响的独立关系不符合帝国主义的定义。'),[Q('imperialism',1,1,'Imperialism involves?','rule or strong influence over other countries','complete political separation with no influence','a grammatical command form','imperialism 指对其他国家的统治或强大影响。'),Q('imperialism',2,1,'An imperialist policy may seek?','resources and influence abroad','to avoid all contact with other countries','to reduce a sentence to an imperative','词条说明这类政策常为获取资源。'),Q('imperialism',3,1,'The suffix -ism often forms a word for?','a policy or system of ideas','a person who acts suddenly','a plural noun','imperialism 指一种政策或制度。'),Q('imperialism',4,1,'Which topic fits a history lecture on imperialism?','how one empire controlled other regions','how a verb forms a command','how a forest blocks a path','帝国控制其他地区属于帝国主义史。')]);
P('imperil','imperil 由 im- 与 peril（危险）构成，表示使某人或某物处于危险之中。',C('imperil.s1','生态保护','Removing the last strip of wetland could imperil the nesting birds that depend on it each spring.','移除最后一片湿地可能危及每年春天依赖它筑巢的鸟类。','Removing the last strip of wetland / could imperil the nesting birds / that depend on it / each spring.','imperil 是及物动词，接处于危险中的对象；could 表示可能性。','失去栖息地会使鸟类面临危险，符合 s1。'),M('The habitat program imperiled the nesting birds by restoring the wetland that protected them.','The habitat program protected the nesting birds by restoring the wetland.','恢复保护栖息地是在保护而非危及鸟类。'),[Q('imperil',1,1,'To imperil a species is to?','put it in danger','guarantee its safety','describe it as funny','imperil 表示危及。'),Q('imperil',2,1,'Which action could imperil a bird population?','destroying its nesting habitat','protecting its wetland','monitoring it carefully','破坏栖息地可能危及鸟类。'),Q('imperil',3,1,'Imperil is closest in meaning to?','endanger','secure','admire','endanger 同样表示使处于危险中。'),Q('imperil',4,1,'In “The leak imperiled the archive,” what was threatened?','the archive','the leak','the repair crew','archive 是 imperil 所影响的对象。')]);
P('impermanence','impermanence 由否定前缀 im- 与 permanence 构成，表示事物不会永远保持不变的性质。',C('impermanence.s1','园艺观察','The gardener accepts the impermanence of spring blossoms and saves their seeds before the petals fall.','园丁接受春花终会凋谢这一无常，并在花瓣落下前收集种子。','The gardener accepts the impermanence of spring blossoms / and saves their seeds / before the petals fall.','impermanence 是抽象名词，表示非永久性；of 引出短暂的事物。','花朵不会始终保持盛开，体现 s1。'),M('The report used impermanence to mean that the mountain would remain exactly unchanged forever.','The report used permanence to describe the mountain as unchanged over time.','永远不变表示 permanence，而非 impermanence。'),[Q('impermanence',1,1,'Impermanence is the fact that something?','does not remain unchanged forever','is permanent by definition','is impossible to understand','impermanence 指非永久性、无常。'),Q('impermanence',2,1,'Fading spring flowers illustrate?','impermanence','imperialism','impermeability','花朵会凋谢体现无常。'),Q('impermanence',3,1,'The prefix im- in impermanence contributes the idea of?','not or opposite','very much','together with','im- 是否定前缀。'),Q('impermanence',4,1,'The closest opposite of impermanence is?','permanence','changeability','briefness','permanence 表示持久不变。')]);
P('impermeable','impermeable 由否定前缀 im- 与 permeable 构成，表示液体或气体无法穿过。',C('impermeable.s1','防水材料','The lining is impermeable to rainwater, keeping the documents dry inside the field case.','内衬不透雨水，使野外工具箱里的文件保持干燥。','The lining is impermeable to rainwater / keeping the documents dry / inside the field case.','impermeable 常用 impermeable to 表示某种物质不能穿过；keeping 补充结果。','雨水无法透过内衬，符合 s1。'),M('The label called the fabric impermeable even though water passed through it immediately.','The label called the fabric permeable because water passed through it immediately.','水能立即穿过的布料并非 impermeable。'),[Q('impermeable',1,1,'An impermeable layer?','blocks liquid or gas from passing through','lets every liquid pass freely','is only a written rule','impermeable 指不透水或气体。'),Q('impermeable',2,1,'An impermeable raincoat lining should?','keep rainwater from passing through','absorb and leak all water','make the wearer speak clearly','不透水内衬会阻止雨水渗透。'),Q('impermeable',3,1,'Which phrase is grammatical?','impermeable to water','impermeable from watering','impermeable by it rains','常用结构是 impermeable to。'),Q('impermeable',4,1,'A close opposite of impermeable is?','permeable','impenetrable in a text sense','imperial','permeable 表示可透过的。')]);
P('impersonal','impersonal 可形容缺乏温度、与具体个人无关的事物，也可作语法术语指没有明确人称主语的形式。',C('impersonal.s1','客户服务','The reply felt impersonal because it used a generic template and never addressed the customer’s specific concern.','这封回复显得冷淡而公式化，因为它用了通用模板，也没有回应客户的具体顾虑。','The reply felt impersonal / because it used a generic template / and never addressed / the customer’s specific concern.','impersonal 在此表示缺少人情味；because 说明回复为什么给人这种感受。','模板化回复没有回应个人问题，符合 s1。'),M('The letter was called impersonal even though it warmly addressed the recipient by name and answered her unique concern.','The letter felt personal because it used the recipient’s name and answered her concern.','有针对性的温暖回应不符合“缺乏个人关怀”。'),[Q('impersonal',1,1,'An impersonal message may feel?','cold or not directed to one particular person','warm and personally attentive','impossible to read through','s1 指冷淡或非针对个人的。'),Q('impersonal',2,2,'An impersonal verb form has?','no definite personal subject','a named speaker in every clause','a strong emotional tone','s2 是语法义。'),Q('impersonal',3,1,'A generic form letter can seem impersonal because it?','does not address the reader’s specific situation','uses the reader’s name and details','offers a personal conversation','套用模板、忽略具体情况会显得冷淡。'),Q('impersonal',4,2,'Which topic uses the grammar sense of impersonal?','a sentence with no definite personal subject','a distant customer-service reply','a ruler’s palace','语法术语指非人称形式。')]);
P('impersonate','impersonate 由 persona（人物、角色）相关词形发展而来，指扮演另一个人的身份、声音或举止。',C('impersonate.s1','舞台表演','For the school comedy, Leon impersonated the strict headmaster, copying his slow walk and formal greeting.','在学校喜剧演出中，利昂模仿严厉的校长，学他慢慢走路和正式问候的样子。','For the school comedy / Leon impersonated the strict headmaster / copying his slow walk / and formal greeting.','impersonate 是及物动词，直接接被扮演的人；copying 说明表演模仿的细节。','喜剧演员模仿校长的举止，符合 s1。'),M('Leon impersonated the headmaster by using his own unrelated voice and making no attempt to act like him.','Leon impersonated the headmaster by copying his voice and manner.','没有模仿对方特征就不构成 impersonate。'),[Q('impersonate',1,1,'To impersonate a person is to?','act as or imitate that person','write a rule about them','put them in danger','impersonate 指扮演或模仿某人。'),Q('impersonate',2,1,'A comedian might impersonate a public figure by copying?','their voice and manner','their passport number only','a weather pattern','表演者会模仿声音和举止。'),Q('impersonate',3,1,'In “Leon impersonated the headmaster,” who was imitated?','the headmaster','Leon’s audience','the school building','宾语 the headmaster 是模仿对象。'),Q('impersonate',4,1,'Which action is impersonation in a stage comedy?','acting in a recognizable character’s manner','reading a neutral list without acting','repairing the stage lights','模仿人物举止用于喜剧表演。')]);
P('impersonation','impersonation 由 impersonate 加名词后缀构成，可指模仿表演，也可指为欺骗而冒充他人。',C('impersonation.s1','喜剧演出','Her impersonation of the radio host captured his familiar pauses and cheerful catchphrase, delighting the audience.','她模仿电台主持人时抓住了他熟悉的停顿和欢快口头禅，逗乐了观众。','Her impersonation of the radio host / captured his familiar pauses / and cheerful catchphrase / delighting the audience.','impersonation 常用 impersonation of someone；此处指娱乐性的模仿表演。','模仿主持人的声音习惯以逗乐观众，符合 s1。'),M('The comedian called the performance an impersonation although she copied no one’s voice or manner.','The comedian called the performance an original character rather than an impersonation.','没有模仿对象的表演不是模仿表演。'),[Q('impersonation',1,1,'An entertainer’s impersonation often involves?','copying someone’s voice and manner','measuring a liquid barrier','implementing a law','s1 指模仿表演。'),Q('impersonation',2,2,'Criminal impersonation means?','pretending to be someone else to deceive','imitating a host for a comedy show','speaking in a different accent for a role','s2 强调冒充以欺骗他人。'),Q('impersonation',3,1,'Which is an entertaining impersonation?','a performer imitates a famous presenter’s catchphrase','a clerk accurately records a name','a singer performs an original song in their own voice','模仿主持人口头禅属于娱乐表演。'),Q('impersonation',4,2,'What makes impersonation deceptive?','the person pretends to be someone else to mislead others','the audience knows it is a comedy act','the performer announces the character openly','隐瞒真实身份并误导他人才是欺骗性冒充。')]);
P('impertinent','impertinent 可指对值得尊重的人鲁莽无礼，也可指与当前问题无关、不切题。',C('impertinent.s1','礼貌沟通','The visitor apologized for an impertinent question about the judge’s private life and returned to the hearing’s subject.','访客为自己询问法官私生活的无礼问题道了歉，并回到听证会主题。','The visitor apologized / for an impertinent question about the judge’s private life / and returned / to the hearing’s subject.','impertinent 修饰 question，表示冒犯、不合礼貌；about 引出问题内容。','询问法官私生活不合礼貌，符合 s1。'),M('The visitor called the question impertinent even though it politely asked about the public hearing’s schedule.','The visitor called the personal question impertinent because it was rude and intrusive.','礼貌询问公开日程并不当然构成无礼。'),[Q('impertinent',1,1,'An impertinent remark is?','rude, especially toward someone deserving respect','carefully respectful','a necessary safety rule','s1 指鲁莽无礼。'),Q('impertinent',2,2,'An impertinent detail in a discussion is?','unrelated to the matter at hand','central to the question','a command form','s2 指不切题。'),Q('impertinent',3,1,'Which question is clearly impertinent in a formal hearing?','one prying into the judge’s private family life','one asking when the hearing starts','one asking where the public entrance is','探问私人生活与正式听证无关且无礼。'),Q('impertinent',4,2,'If a fact is impertinent to the report, it?','does not relate to the report’s subject','supports the main conclusion directly','is required by law','impertinent 的旧义与 irrelevant 接近。')]);
P('impervious','impervious 源自拉丁语 impervius，含“不让通过”之意，可指物质不透水，也可指人不受影响。',C('impervious.s1','材料测试','The coating proved impervious to salt water, so the metal rail showed no corrosion after months by the shore.','测试证明这种涂层不透盐水，因此金属栏杆在海边数月后仍未腐蚀。','The coating proved impervious to salt water / so the metal rail showed no corrosion / after months by the shore.','impervious 常接 to，表示不让某种液体或影响穿透；so 引出保护结果。','盐水无法穿过涂层并腐蚀金属，符合 s1。'),M('The test called the coating impervious to water even though water passed through it and soaked the metal.','The test called the coating permeable because water passed through it.','水能穿透材料，不符合 impervious。'),[Q('impervious',1,1,'An impervious surface?','does not let water or another substance pass through','absorbs every liquid immediately','is easy to cross on foot','s1 指不透过。'),Q('impervious',2,2,'Someone impervious to criticism is?','not influenced by it','deeply affected by every comment','unable to understand a map','s2 表示不受影响。'),Q('impervious',3,1,'Which phrase is natural?','impervious to salt water','impervious for salt watering','impervious by a salty','常用搭配 impervious to。'),Q('impervious',4,2,'If she remained impervious to the pressure, she?','was not swayed by it','let it change her decision immediately','measured its depth','不受压力影响符合 s2。')]);
P('impetuous','impetuous 源于 impetus 相关词族，形容因一时情绪而突然行动、缺少审慎的。',C('impetuous.s1','旅行计划','In an impetuous moment, Ravi booked a costly trip before checking whether he could take time off work.','拉维一时冲动订下昂贵旅程，却没先确认自己能否请到假。','In an impetuous moment / Ravi booked a costly trip / before checking / whether he could take time off work.','impetuous 修饰 moment，表示冲动、未经仔细考虑；before 引出他忽略的核查步骤。','先订昂贵旅程、后核实时间体现欠考虑，符合 s1。'),M('Ravi made an impetuous decision after comparing the options carefully for months and confirming every detail.','Ravi made a considered decision after comparing the options and confirming every detail.','经过数月仔细比较和核实的决定不是冲动鲁莽的。'),[Q('impetuous',1,1,'An impetuous decision is made?','suddenly, from feeling rather than careful thought','only after extensive careful review','by following a required command','impetuous 表示冲动、未经考虑。'),Q('impetuous',2,1,'Which action is impetuous?','buying an expensive ticket on a sudden urge','checking prices and dates for weeks first','waiting until all information is available','凭一时冲动购买符合该义。'),Q('impetuous',3,1,'The closest opposite of impetuous is?','careful and considered','rash','hasty','careful and considered 与冲动相反。'),Q('impetuous',4,1,'An impetuous person may act before?','thinking through the consequences','feeling any emotion','seeing another person','该词强调没有先仔细思考。')]);
P('impetus','impetus 源自拉丁语 impetus，原指冲击或推动力，可指促使事情发展、运动的因素或力量。',C('impetus.s1','社区项目','A small grant gave the neighborhood garden an impetus by funding tools and bringing more volunteers into the project.','一笔小额拨款为社区花园注入了动力，既购置了工具，也吸引了更多志愿者参与。','A small grant gave the neighborhood garden an impetus / by funding tools / and bringing more volunteers / into the project.','give something an impetus 表示为其提供推动力；by 引出拨款发挥作用的方式。','拨款帮助项目更快发展，符合 s1。'),M('The grant gave the garden an impetus by preventing the team from buying tools or recruiting any volunteers.','The grant slowed the garden project by preventing the team from getting tools or help.','阻止项目获取资源会削弱动力，而不是推动发展。'),[Q('impetus',1,1,'An impetus for change is?','something that encourages change to develop','a reason to keep everything unchanged','a grammar command','impetus 指促进发展的推动因素。'),Q('impetus',2,2,'The impetus of a moving object can refer to its?','force or energy of motion','color shade','religious song','s2 可指运动或发展的力量、势头。'),Q('impetus',3,3,'In physics, impetus is described as?','the force that makes a body move','a statement left unsaid','a tool used for gardening','s3 是物理中的推动力。'),Q('impetus',4,1,'Which could give a project impetus?','new funding that helps it expand','a rule that cancels all activity','a report unrelated to it','能帮助项目发展的资源可提供 impetus。')]);
P('impinge','impinge 源自拉丁语 impingere（撞上），现常用 impinge on 表示对某人或某事造成限制性影响。',C('impinge.s1','隐私保护','The new camera policy should not impinge on employees’ privacy in changing areas.','新的摄像头政策不应侵犯员工在更衣区域的隐私。','The new camera policy / should not impinge on employees’ privacy / in changing areas.','impinge on 表示影响或侵犯某事物；should not 表示规范性限制。','在更衣区拍摄会限制隐私，符合 s1。'),M('The policy did not impinge on privacy because it secretly recorded every private conversation.','The policy impinged on privacy because it secretly recorded private conversations.','秘密录下私人谈话侵犯了隐私，不能说没有影响。'),[Q('impinge',1,1,'To impinge on privacy is to?','affect or restrict it','protect it completely','write a humorous note about it','impinge on 可表示侵犯、限制。'),Q('impinge',2,1,'Which sentence uses impinge naturally?','The rule may impinge on personal freedom.','The rule impinges a colorful hue.','She impinged to sing a hymn.','常用结构是 impinge on。'),Q('impinge',3,1,'A policy that impinges on access?','limits people’s access','guarantees unrestricted access','measures access in hundreds','该动词表示产生限制性影响。'),Q('impinge',4,1,'What does impinge most nearly mean here?','have an effect, especially a limiting one','make an exact copy','act without a plan','impinge 强调影响，尤其是限制。')]);
P('impious','impious 由否定前缀 im- 与 pious（虔诚的）构成，表示不敬宗教，较少见时也指不孝。',C('impious.s1','文学评论','The critic described the fictional king’s impious speech as a deliberate challenge to the temple’s religious authority.','评论者把小说中这位国王不敬的言论称作对神殿宗教权威的刻意挑战。','The critic described the fictional king’s impious speech / as a deliberate challenge / to the temple’s religious authority.','impious 修饰 speech，表示缺少宗教敬意；as 引出评论者对其作用的判断。','言论被描写为不尊重宗教权威，符合 s1。'),M('The reviewer called the prayer impious even though it expressed deep reverence for the religion.','The reviewer called the prayer pious because it expressed deep religious reverence.','表达深切敬意的祈祷与 impious 的含义相反。'),[Q('impious',1,1,'An impious remark shows?','a lack of reverence for religion','deep religious devotion','a strong wish to help others','impious 表示不虔诚、不敬。'),Q('impious',2,1,'Which could be called impious in a story?','speech deliberately mocking a sacred practice','a respectful prayer','a neutral weather report','嘲弄宗教仪式可被称为不敬。'),Q('impious',3,1,'The prefix im- in impious suggests?','the opposite or absence of piety','a hundred times more piety','a person who studies water','im- 在此构成否定义。'),Q('impious',4,1,'A less common extension of impious can mean?','disrespectful toward one’s parents','unable to pass through a wall','very influential','词条还收录较少见的“不孝”义。')]);
P('implant','implant 源自拉丁语 implantare（种入），可指把东西固定植入身体，也可指把观念植入心中。',C('implant.s1','医疗护理','The surgeon implanted a small hearing device beneath the patient’s skin after discussing the procedure and its risks.','在讨论手术和风险后，外科医生把一枚小型助听设备植入了患者皮下。','The surgeon implanted a small hearing device / beneath the patient’s skin / after discussing the procedure / and its risks.','implant 是及物动词，后接植入物；beneath 指位置，after 引出事前沟通。','设备被固定在身体组织内，符合 s1。'),M('The surgeon implanted the device by leaving it on the bedside table outside the patient’s body.','The surgeon placed the device beneath the patient’s skin.','放在床头柜上并未植入身体。'),[Q('implant',1,1,'To implant a device in the body is to?','fix it inside the body','place it on a nearby table','describe how it works','implant 可指植入身体。'),Q('implant',2,1,'A teacher may implant an idea in a student’s mind by?','helping it take root there','removing every memory','measuring the student’s height','implant 也可比喻使观念深入人心。'),Q('implant',3,1,'Which phrase is natural?','implant a sensor beneath the skin','implant a road to the house','implant someone for an idea','implant 后接植入对象。'),Q('implant',4,1,'In the medical example, what was implanted?','a small hearing device','the surgeon','the procedure’s risk','device 是植入物。')]);
P('implausible','implausible 由否定前缀 im- 与 plausible 构成，表示难以相信或缺乏可信度。',C('implausible.s1','新闻核查','The witness’s account seemed implausible because the dates changed each time she retold the story.','证人的说法似乎难以置信，因为她每次复述时日期都不一样。','The witness’s account seemed implausible / because the dates changed / each time she retold the story.','implausible 修饰 account，表示可信度低；because 给出怀疑的依据。','日期反复变化削弱说法的可信度，符合 s1。'),M('The explanation was implausible because every detail was independently confirmed by records and witnesses.','The explanation was plausible because records and witnesses confirmed its details.','各方记录都证实细节，会增强可信度而非削弱。'),[Q('implausible',1,1,'An implausible story is?','hard to believe','certainly true','easy to verify from direct records','implausible 表示难以相信。'),Q('implausible',2,1,'Which detail makes an account implausible?','the dates change repeatedly without explanation','several records confirm the same date','a witness provides clear evidence','缺乏解释的矛盾会削弱可信度。'),Q('implausible',3,1,'The prefix im- changes plausible to mean?','not plausible','more plausible','slightly important','否定前缀构成相反含义。'),Q('implausible',4,1,'A close opposite of implausible is?','credible','impenetrable','impetuous','credible 表示可信。')]);
P('implement','implement 可作动词表示实施计划或落实决定，也可作名词指工作所用的工具。',C('implement.s1','政策执行','The council will implement the recycling plan in stages, beginning with public buildings next month.','市议会将分阶段实施回收计划，下个月先从公共建筑开始。','The council will implement the recycling plan / in stages / beginning with public buildings / next month.','implement 作及物动词，表示把计划付诸实行；beginning 补充阶段安排。','计划将实际投入运行，符合 s1。'),M('The council implemented its recycling plan by shelving it permanently and taking no steps to put it into operation.','The council postponed its recycling plan instead of implementing it.','永久搁置计划不是实施计划。'),[Q('implement',1,1,'To implement a policy is to?','put it into operation','write an idea and never act on it','import it from another country','动词 implement 表示实施政策。'),Q('implement',2,2,'To implement an agreement is to?','carry out its terms','ignore every commitment','translate it without action','s2 指落实决定或协议。'),Q('implement',3,3,'A gardening implement is?','a tool used for a job','a person who imports goods','an abstract implication','名词 implement 指工具。'),Q('implement',4,1,'Which sentence uses the verb sense?','The school implemented a new attendance system.','She picked up a garden implement.','The implication was clear.','implemented a system 表示实施系统。')]);
P('implementation','implementation 由 implement 加 -ation 构成，指使计划、法律或制度真正运作起来的过程。',C('implementation.s1','法律实施','The implementation of the new safety rule begins in June, after staff have completed their training.','新安全规定的实施将于六月开始，届时员工已完成培训。','The implementation of the new safety rule / begins in June / after staff have completed / their training.','implementation of 表示某计划或规定的实施；after 从句说明开始前的准备。','规定开始实际执行，符合 s1。'),M('The report called a rule’s implementation complete even though nobody followed it and no process had begun.','The report called the rule’s implementation incomplete because it had not begun in practice.','没有开始实际执行，就不能说已完成实施。'),[Q('implementation',1,1,'Implementation of a plan means?','making the plan work in practice','thinking of it without acting','writing an unrelated summary','implementation 指使计划实际运转。'),Q('implementation',2,1,'Implementation often follows?','a decision to put a policy into effect','the permanent cancellation of the policy','a change in its spelling only','通常在决策后落实政策。'),Q('implementation',3,1,'Which phrase is standard?','implementation of the law','implementation under the law of','implementation to the law in','常用结构 implementation of。'),Q('implementation',4,1,'Training before a new rule starts supports?','its implementation','its impersonation','its impermanence','培训有助于实际落实规定。')]);
P('implicate','implicate 源自拉丁语 implicare（缠绕、牵涉），在此指证据显示某人与犯罪有关，常用 implicate in。',C('implicate.s1','财务调查','The audit trail implicated a senior manager in the false invoices, although investigators had not yet announced a verdict.','审计记录显示一名高级经理牵涉伪造发票，但调查人员尚未宣布结论。','The audit trail implicated a senior manager / in the false invoices / although investigators / had not yet announced a verdict.','implicate someone in something 表示显示其卷入某事；although 提醒这还不是最终裁决。','审计记录把经理与伪造发票关联起来，符合 s1；例句不预断定罪。'),M('The report said the audit trail implicated the manager but also stated that it contained no link between him and the invoices.','The report said the audit trail did not implicate the manager because it found no link to the invoices.','没有任何关联证据就不能说记录牵涉此人。'),[Q('implicate',1,1,'To implicate someone in a crime is to?','show evidence connecting them with it','prove they were nowhere near it','ask them to implement a plan','implicate 指显示某人可能与犯罪有关。'),Q('implicate',2,1,'Which construction is common?','implicate someone in fraud','implicate someone for a gift','implicate someone at a color','常见搭配是 implicate in。'),Q('implicate',3,1,'An audit trail implicating a manager is?','evidence linking the manager to the questioned activity','a final court verdict in every case','a tool used to print invoices','该词表示牵连证据，不等于裁决。'),Q('implicate',4,1,'In the example, had investigators announced a verdict?','No, the investigation was still ongoing.','Yes, the manager was already convicted.','The audit trail was not mentioned.','例句明确说尚未宣布结论。')]);
P('implication','implication 来自 implicate 的名词形式，指言语中暗示但没有明说的含义。',C('implication.s1','会议纪要','The implication of Dana’s reply was that the budget proposal needed more evidence before approval.','达娜答复中的言下之意是，预算提案在批准前还需要更多证据。','The implication of Dana’s reply / was that the budget proposal needed more evidence / before approval.','implication of X 常指 X 暗示的意思；that 从句说明言外之意。','她没有直说否决，而是暗示仍缺证据，符合 s1。'),M('The implication was explicit because Dana stated every concern directly and left nothing unsaid.','Dana made her concerns explicit rather than leaving an implication.','完全直接说出的内容不是未明说的暗示。'),[Q('implication',1,1,'An implication is?','a meaning hinted at but not stated directly','a fully unrelated fact','a physical barrier to water','implication 指言下之意。'),Q('implication',2,1,'What is the implication of “We need more data first”?','approval may have to wait for more evidence','the data are already complete','the meeting has been canceled forever','这句话暗示需要更多数据后再决定。'),Q('implication',3,1,'Which phrase is natural?','the implication of her reply','the implication under her reply of','the implication at her replied','常用结构 the implication of。'),Q('implication',4,1,'A speaker leaves an implication when they?','hint at something without saying it plainly','state every point directly','make a tool for a job','该词指暗示而非明说。')]);
P('implicit','implicit 可表示未直接说出但可理解、作为必要部分内含，也可表示完全信任、毫不怀疑。',C('implicit.s1','团队讨论','There was implicit criticism in the memo: it never named the delays, but its request for weekly reports made the concern clear.','备忘录里含有隐晦的批评：它没有点名延误，但要求每周提交报告表明了担忧。','There was implicit criticism in the memo / it never named the delays / but its request for weekly reports / made the concern clear.','implicit criticism 是未明说而可领会的批评；but 对比没有直说与读者能理解的意思。','批评未直接表述，但由报告要求暗示出来，符合 s1。'),M('The memo’s criticism was implicit because it stated the complaint openly in its first sentence.','The memo’s criticism was explicit because it stated the complaint openly.','开门见山的批评是 explicit，不是 implicit。'),[Q('implicit',1,1,'Implicit criticism is?','hinted at rather than stated directly','written in bold and stated openly','a command in grammar','s1 指未明说但可理解。'),Q('implicit',2,2,'A quality implicit in a plan is?','contained in it as a necessary part','unrelated to it','only a spoken order','s2 表示内含于其中。'),Q('implicit',3,3,'Implicit trust means?','complete trust without doubt','a cautious suspicion','a rule stated indirectly','s3 指绝对信任。'),Q('implicit',4,1,'Which is an implicit warning?','a hint that trouble may follow, without saying so directly','a clear sentence saying “This is a warning”','a list of unrelated dates','暗示而未明说的提醒符合 s1。')]);
P('implicitly','implicitly 是 implicit 的副词，可表示隐含地，也可表示毫无保留、绝对地信任。',C('implicitly.s2','合作关系','The two researchers trusted each other implicitly and shared preliminary findings without demanding repeated proof.','两位研究人员毫无保留地相互信任，分享初步发现时不要求反复证明。','The two researchers trusted each other implicitly / and shared preliminary findings / without demanding / repeated proof.','trust implicitly 是固定搭配，表示绝对信任；without 补充这种信任的表现。','他们无需反复验证对方诚意，符合 s2。'),M('The researchers trusted each other implicitly but demanded proof of every routine statement before listening.','The researchers trusted each other cautiously because they checked every claim first.','每句话都要求先证明，说明信任并非毫无保留。'),[Q('implicitly',1,1,'An instruction given implicitly is?','suggested without being said directly','spelled out in exact words','given as a physical impulse','s1 指隐含地。'),Q('implicitly',2,2,'To trust someone implicitly is to trust them?','completely and without doubt','only after checking every small claim','not at all','s2 指绝对信任。'),Q('implicitly',3,2,'Which phrase is a common collocation?','trust implicitly','import implicitly a machine','impinge implicitly on a road','常见搭配是 trust implicitly。'),Q('implicitly',4,1,'If a contract implicitly allows a choice, does it state it directly?','No, the permission is understood rather than directly stated.','Yes, it lists the choice explicitly.','No, it makes the choice impossible.','implicitly 的此义是未直接说出。')]);
P('implied','implied 是 imply 的过去分词形容词，表示通过言语或情境暗示、没有明说的。',C('implied.s1','工作邮件','The implied criticism in the email was that the team had missed several agreed deadlines.','邮件中隐含的批评是团队错过了几个约定的截止日期。','The implied criticism in the email / was that the team / had missed several agreed deadlines.','implied 修饰 criticism，表示暗示出来的；that 从句说明其内容。','批评的内容可从邮件中读出，但没有直接说出，符合 s1。'),M('The email contained implied criticism even though it stated the complaint in direct, unmistakable words.','The email contained explicit criticism because it stated the complaint directly.','直接明说的批评不是 implied。'),[Q('implied',1,1,'An implied meaning is?','hinted at but not stated','written out in full','impossible by definition','implied 指暗含、未明说的。'),Q('implied',2,1,'An implied threat may be?','a warning suggested indirectly','a signed guarantee of safety','a grammar tense','暗示性的威胁没有直说。'),Q('implied',3,1,'Which is an implied criticism?','a comment that hints the work was late without saying so','a sentence saying “Your work was late”','a neutral list of page numbers','间接暗示延误符合 implied。'),Q('implied',4,1,'Implied is related to the verb?','imply','impel','implant','implied 是 imply 的过去分词形式。')]);
P('implore','implore 源自拉丁语 implorare，有呼求援助之意，表示强烈恳求。',C('implore.s1','救援沟通','The hikers implored the ranger to wait until the fog lifted before leading the group across the ridge.','徒步者恳求护林员等到雾散后再带队穿过山脊。','The hikers implored the ranger / to wait until the fog lifted / before leading the group / across the ridge.','implore someone to do 表示恳求某人做某事；until 从句说明恳求内容。','徒步者急切请求护林员暂缓行动，符合 s1。'),M('The hikers implored the ranger to leave at once by politely saying they had no request and were happy with the delay.','The hikers asked the ranger to wait because they were concerned about the fog.','说自己没有请求不是恳求对方采取行动。'),[Q('implore',1,1,'To implore someone is to?','beg them earnestly','give them a tool','state an implication indirectly','implore 表示强烈恳求。'),Q('implore',2,1,'Which construction is standard?','implore someone to wait','implore someone waiting at','implore for someone to waiting','常用结构 implore someone to do。'),Q('implore',3,1,'A person may implore for help when they?','urgently beg someone to help','have no need or wish for help','want to impose a tax','恳求通常带有迫切请求。'),Q('implore',4,1,'In the example, what did the hikers ask the ranger to do?','wait for the fog to lift','cross immediately','leave them on the ridge','答案应与恳求内容一致。')]);
P('imply','imply 源自拉丁语 implicare，可表示间接暗示、意味着，也可用于逻辑上蕴含。',C('imply.s1','讨论纪要','The chair’s silence did not necessarily imply agreement, so the secretary asked each member to state a vote.','主席的沉默不一定意味着赞同，因此秘书请每位成员明确表决。','The chair’s silence did not necessarily imply agreement / so the secretary asked each member / to state a vote.','imply agreement 表示暗示或意味着赞同；not necessarily 避免把沉默误当成确定同意。','沉默可能暗示某种态度，但不必然等于同意，符合 s1。'),M('The minutes said silence implied agreement but also recorded that every member had explicitly voted against the proposal.','The minutes said silence did not imply agreement because members had voted against the proposal.','明确反对的记录与“沉默意味着同意”相矛盾。'),[Q('imply',1,1,'To imply something is to?','suggest it indirectly','say it in exact words','make it impossible to happen','imply 的 s1 指间接暗示。'),Q('imply',2,2,'“A red light implies that the road is closed” means it?','means or indicates that the road is closed','is unrelated to the road','physically closes the road itself','s2 可表示意味着或表明。'),Q('imply',3,3,'In logic, A implies B when?','B follows as a logical consequence of A','A and B are unrelated','A is a tool used for B','逻辑义表示 A 必然包含 B。'),Q('imply',4,1,'Why not say silence always implies consent?','Silence may not state a person’s view directly.','Imply always means shout loudly.','Silence is a type of grammar tense.','暗示不能自动等同明确同意。')]);
P('impolite','impolite 由否定前缀 im- 与 polite 构成，表示言行不礼貌、欠缺礼节。',C('impolite.s1','餐桌礼仪','It is impolite to interrupt someone repeatedly while they are explaining their point.','别人正在解释观点时反复打断对方是不礼貌的。','It is impolite / to interrupt someone repeatedly / while they are explaining / their point.','It is impolite to do 是评价行为不礼貌的常用结构；while 表示打断发生的时机。','反复打断正在发言的人违反基本礼貌，符合 s1。'),M('The host called it impolite to listen patiently and wait for the speaker to finish.','The host called it polite to listen patiently and wait for the speaker to finish.','耐心倾听、等对方说完是有礼貌的。'),[Q('impolite',1,1,'An impolite action is?','rude in manners','considerate and respectful','a type of water barrier','impolite 表示不礼貌。'),Q('impolite',2,1,'Which behavior is impolite in a conversation?','repeatedly interrupting the speaker','waiting for a turn to speak','listening without mocking','反复打断他人是不礼貌的。'),Q('impolite',3,1,'The prefix im- in impolite makes the word mean?','not polite','extremely polite','polite to everyone','im- 是否定前缀。'),Q('impolite',4,1,'A close opposite of impolite is?','courteous','rude','impertinent','courteous 表示有礼貌。')]);
P('import','import 可作动词表示从国外输入商品，也可作名词指进口品、进口活动或正式语境中的重要性与含意。',C('import.s1','贸易运输','The company imports medical gloves from two countries to keep local clinics supplied during shortages.','这家公司从两个国家进口医用手套，以便在短缺期间持续供应本地诊所。','The company imports medical gloves / from two countries / to keep local clinics supplied / during shortages.','import 作及物动词，表示从国外输入商品；from 引出来源地。','手套从国外运入本国，符合 s1。'),M('The company imported gloves by sending its locally made products abroad for foreign buyers.','The company exported its locally made gloves to foreign buyers.','把本国产品运往国外是 export，不是 import。'),[Q('import',1,1,'To import goods is to?','bring them into a country from abroad','send them out of the country','make them impossible','动词 import 指进口。'),Q('import',2,2,'An import is?','a product brought in from another country','a local product sent overseas','a grammar command','名词 import 可指进口货。'),Q('import',3,3,'Import can also refer to?','the act or business of importing','the act of making a painting','a sudden emotional urge','s3 指进口活动或业务。'),Q('import',4,4,'In formal use, “the import of her words” means?','their importance or meaning','the goods she bought abroad','the act of shipping items','s4 表示重要性或含意。')]);
P('importance','importance 来自 important，表示某人或某事值得注意、具有重要价值的性质。',C('importance.s1','公共卫生','The report stresses the importance of clean drinking water for preventing illness in the region.','报告强调了清洁饮用水对预防该地区疾病的重要性。','The report stresses the importance of clean drinking water / for preventing illness / in the region.','importance 常用 the importance of 表示某事物的重要性；for 引出其价值所在。','饮用水与疾病预防有关，值得特别重视，符合 s1。'),M('The report emphasized the importance of clean water but concluded that it had no value or relevance to health.','The report emphasized the value of clean water for protecting health.','声称水无价值与强调其重要性自相矛盾。'),[Q('importance',1,1,'Importance is the quality of?','being worth notice or attention','being impossible to understand','being a sudden impulse','importance 指重要性。'),Q('importance',2,1,'Why discuss the importance of clean water?','because it matters for health','because it is unrelated to health','because it is only a grammar form','健康影响说明饮水值得重视。'),Q('importance',3,1,'Which phrase is standard?','the importance of a decision','the importance for a decision’s of','an importance under of decision','常用搭配 the importance of。'),Q('importance',4,1,'A person may stress the importance of a rule to show?','why the rule deserves attention','that the rule is irrelevant','that it cannot be followed','强调重要性就是说明值得关注。')]);
P('important','important 可指影响或价值重大，也可指有影响力、有地位，或对某人有很大价值。',C('important.s3','个人目标','Learning to read was important to Mina because it let her manage her appointments without assistance.','学会阅读对米娜很重要，因为这让她无需他人帮助也能管理自己的预约。','Learning to read was important to Mina / because it let her manage her appointments / without assistance.','important to someone 表示对某人有价值或关系重大；because 解释其个人价值。','阅读对米娜的独立生活有重要价值，符合 s3。'),M('Mina said reading was important to her but explained that it had no value and made no difference in her life.','Mina said reading was unimportant to her because it made no difference in her life.','声称没有价值、没有影响与“重要”矛盾。'),[Q('important',1,1,'An important discovery has?','great effect or value','no effect at all','a hidden meaning only','s1 指影响或价值重大。'),Q('important',2,2,'An important official may be?','powerful or influential','unnoticed and without authority','a physical barrier','s2 指有影响力或地位。'),Q('important',3,3,'If reading is important to Mina, it?','has great value or matters to her','is unrelated to her life','is impossible for her to do','s3 指对某人有价值。'),Q('important',4,1,'Which event is likely to be important?','a decision that changes the town’s water supply','a minor mark on a disposable scrap','a detail with no effect on anyone','重大影响符合 important。')]);
P('importation','importation 由 import 加 -ation 构成，指把商品带入一个国家的行为或过程。',C('importation.s1','海关统计','The importation of specialty coffee increased after the port introduced a faster inspection process.','港口启用更快的检查流程后，特色咖啡的进口量有所增加。','The importation of specialty coffee increased / after the port introduced / a faster inspection process.','importation of 指某类商品的进口；after 表示变化发生在流程改进之后。','咖啡被带入本国，符合进口过程义 s1。'),M('The report described the importation of coffee as the act of shipping locally grown beans out to foreign buyers.','The report described the export of locally grown coffee to foreign buyers.','把本国产品运往外国是出口，不是进口。'),[Q('importation',1,1,'Importation is the act of?','bringing goods into a country','sending local goods abroad','making an item by hand','importation 指进口过程。'),Q('importation',2,1,'A rise in coffee importation means?','more coffee is being brought in from abroad','more coffee is being shipped abroad','coffee is no longer traded','进口上升表示输入的咖啡更多。'),Q('importation',3,1,'Which phrase is natural?','the importation of machinery','the importation to foreign customers abroad','an importation of exporting goods out','常用结构 importation of goods。'),Q('importation',4,1,'Importation is closely related to the verb?','import','impress','impose','importation 由 import 派生。')]);
P('importer','importer 由 import 加表示施事者的 -er 构成，指经营进口商品的人或公司。',C('importer.s1','商业往来','The importer checked the country-of-origin documents before releasing the tea shipment to local shops.','进口商在把这批茶叶发往本地商店前，核对了原产地文件。','The importer checked the country-of-origin documents / before releasing the tea shipment / to local shops.','importer 指进口商品的经营者；before 引出发货前的核查步骤。','公司负责把国外茶叶引入本地市场，符合 s1。'),M('The importer was described as a business that only sent locally produced tea to overseas buyers.','The exporter was described as a business that sent locally produced tea overseas.','只把本地商品运出国的是 exporter，不是 importer。'),[Q('importer',1,1,'An importer is someone whose business is?','bringing goods in from abroad','sending goods abroad only','repairing farm tools','importer 指进口者或进口商。'),Q('importer',2,1,'Which company is an importer?','a firm bringing foreign tea into the local market','a firm shipping local tea overseas','a company growing tea domestically only','进口商把外国商品带入本地市场。'),Q('importer',3,1,'The suffix -er here identifies?','a person or business that imports','a quality of importance','a past-tense action','-er 表示从事进口的人或公司。'),Q('importer',4,1,'An importer may need to check?','country-of-origin documents','the grammar of an imperative sentence','whether a road is impenetrable','进口业务常核对原产地文件。')]);
P('importune','importune 源自拉丁语 importunare，有纠缠、不断请求之意，表示反复恳求或强求。',C('importune.s1','工作沟通','The vendor continued to importune the director for an immediate answer, although the review was not due until Friday.','尽管评审要到周五才结束，供应商仍不断催求主管立即答复。','The vendor continued to importune the director / for an immediate answer / although the review / was not due until Friday.','importune 表示反复恳求或要求；although 对比催促与原定时间。','供应商一再要求答复，符合 s1。'),M('The vendor importuned the director by making one polite request and then never asking again.','The vendor asked once politely rather than repeatedly importuning the director.','只礼貌询问一次不属于反复纠缠。'),[Q('importune',1,1,'To importune someone is to?','beg or demand from them repeatedly','thank them once','implement their proposal','importune 指反复恳求、强求。'),Q('importune',2,1,'A caller who importunes a clerk may?','keep pressing the clerk for an answer','ask one brief question and leave','silently read a notice','该词含有一再要求的意味。'),Q('importune',3,1,'Which tone best fits importune?','persistent and demanding','casual and finished','purely descriptive','importune 描写持续强求。'),Q('importune',4,1,'The vendor importuned the director for?','an immediate answer','a copy of a hymn','a water-resistant coating','句中 for 引出反复索求的内容。')]);
P('impose','impose 可指强迫接受、官方征收税罚、推行制度，也可指给别人添麻烦或要求他人帮忙。',C('impose.s3','新规执行','The city will impose a nighttime noise limit near the hospital starting on the first of July.','市政府将从七月一日起在医院附近推行夜间噪声限制。','The city will impose a nighttime noise limit / near the hospital / starting on the first of July.','impose a rule/limit 表示正式实施规定；starting 补充生效时间。','市政府正式推行规则，符合 s3。'),M('The city imposed a noise limit by officially abolishing it before it ever took effect.','The city abolished the noise limit rather than imposing it.','废除规定与正式推行规定意思相反。'),[Q('impose',1,1,'To impose an idea on someone is to?','force them to accept it','invite them to ignore it','ask what they think first','s1 指把想法强加给别人。'),Q('impose',2,2,'A government may impose?','a tax or fine officially','a humorous story','a color shade','s2 指官方征税或处罚。'),Q('impose',3,3,'To impose a new rule is to?','officially put it in place','cancel it before use','hint at it indirectly','s3 指正式推行规定。'),Q('impose',4,4,'“I do not want to impose on my host” means?','I do not want to make an unreasonable demand on them','I plan to tax them','I will order them to accept an idea','s4 指打扰或让别人为自己做事。')]);
P('imposing','imposing 由 impose 派生，形容外观宏伟、强健，给人以敬畏或深刻印象。',C('imposing.s1','建筑参观','The imposing stone library dominates the square, with tall columns and a broad staircase leading to its entrance.','这座气势宏伟的石砌图书馆俯瞰广场，高大的柱子和宽阔台阶通向入口。','The imposing stone library / dominates the square / with tall columns and a broad staircase / leading to its entrance.','imposing 修饰 library，表示建筑宏伟、醒目；with 短语呈现其外观特征。','高柱和宽阔台阶营造出庄严壮观的印象，符合 s1。'),M('The guide called the imposing library tiny and unimpressive, with no visible structure or entrance.','The guide called the modest building unimpressive rather than imposing.','毫不起眼的小建筑不符合 imposing 的宏伟醒目义。'),[Q('imposing',1,1,'An imposing building looks?','grand and strong','small and barely noticeable','impossible to enter by definition','imposing 表示壮观、气派。'),Q('imposing',2,1,'Which sight is imposing?','a vast hall with tall columns','a tiny shed hidden behind a wall','a blank piece of paper','宏伟大厅给人强烈印象。'),Q('imposing',3,1,'The adjective imposing can describe?','something grand in appearance','a person who imports goods only','a hint left unsaid','该词形容外观壮观的事物。'),Q('imposing',4,1,'A close description of an imposing entrance is?','impressive and commanding','ordinary and easy to overlook','unrelated to the building','气派的入口符合 imposing。')]);
P('imposition','imposition 可指官方征收税款、罚款或实施规定，也可指强加给他人的不合理要求。',C('imposition.s2','邻里交往','Asking a neighbor to watch three children for a week would be an imposition, so Kai arranged paid childcare instead.','请邻居照看三个孩子一周会给对方添很大负担，因此凯改为安排付费托育。','Asking a neighbor to watch three children for a week / would be an imposition / so Kai arranged paid childcare / instead.','imposition 在此指给他人造成的不合理负担；so 引出替代安排。','长期要求邻居提供大量照料会占用其时间，符合 s2。'),M('Kai called the request an imposition even though it was a tiny favor the neighbor had freely offered.','Kai accepted the neighbor’s freely offered small favor without treating it as a burden.','对方主动提出的小忙并不必然是不合理负担。'),[Q('imposition',1,1,'An imposition by an authority may be?','the introduction of a tax, fine, or rule','a private joke','a sudden impulse','s1 指官方征收或实施。'),Q('imposition',2,2,'A demand that unfairly uses someone’s time is?','an imposition','an importer','an imperfect tense','s2 指不合理地占用他人时间或好意。'),Q('imposition',3,2,'Which could be an imposition on a neighbor?','asking them for a week of unpaid childcare at short notice','thanking them for a brief favor','declining their offer politely','过度要求会给邻居造成负担。'),Q('imposition',4,1,'The imposition of a new tax is its?','official introduction','quiet cancellation','informal implication','impose 税收的名词形式可指征收。')]);
P('impossible','impossible 可指无法发生或做到、难以应付的人或事，也可口语表示荒谬得讲不通。',C('impossible.s1','工程评估','It is impossible to finish the bridge inspection before sunrise because several sections are still closed to engineers.','由于几个路段仍未向工程师开放，要在日出前完成桥梁检查是不可能的。','It is impossible to finish the bridge inspection / before sunrise / because several sections / are still closed to engineers.','It is impossible to do 是常见句型；because 说明任务无法完成的现实原因。','封闭路段使检查无法按时完成，符合 s1。'),M('The engineer called the inspection impossible although every section was open and the team had finished it already.','The engineer called the inspection complete because every section was open and checked.','任务已经完成且所有路段开放，不符合“不可能做到”。'),[Q('impossible',1,1,'An impossible task?','cannot be done or happen','has already happened','is only mildly inconvenient','s1 表示不可能。'),Q('impossible',2,2,'An impossible person to please is?','very difficult to satisfy','easy to satisfy','a person who imports goods','s2 指难以对付或取悦。'),Q('impossible',3,3,'An impossible excuse in casual speech may be?','absurd or unreasonable','perfectly logical and convincing','a tax imposed by law','s3 可口语表示荒谬。'),Q('impossible',4,1,'Which is impossible under the stated conditions?','finishing an inspection when sections remain closed','checking an open section','rescheduling the inspection','封闭区域使按时检查无法完成。')]);
P('impostor','impostor 源自拉丁语 impostor，指冒充他人身份或身份资格的骗子。',C('impostor.s1','身份核验','The gallery discovered that the supposed appraiser was an impostor after checking the credentials with the issuing association.','画廊向颁发机构核验资历后，发现那位所谓的评估师是假冒者。','The gallery discovered / that the supposed appraiser was an impostor / after checking the credentials / with the issuing association.','impostor 指冒充者；after 引出发现其真实身份的核验过程。','此人假扮有资质的评估师，符合 s1。'),M('The gallery called a licensed appraiser an impostor even though the issuing association confirmed her credentials.','The gallery confirmed that the licensed appraiser was genuine after checking her credentials.','资质得到颁发机构确认的人不是冒充者。'),[Q('impostor',1,1,'An impostor is someone who?','pretends to be another person or to have a false identity','states their identity truthfully','imports goods for a company','impostor 指冒充者。'),Q('impostor',2,1,'How did the gallery discover the impostor?','it checked the claimed credentials','it found a hymn','it measured the building’s height','核验证书发现身份不实。'),Q('impostor',3,1,'A person posing as a licensed appraiser without credentials is?','an impostor','an importer','an impetus','假冒专业身份的人是 impostor。'),Q('impostor',4,1,'The closest opposite of impostor is?','a genuine, correctly identified person','a deceptive pretender','a person who imposes rules','genuine 与冒充相反。')]);
P('impotence','impotence 可表示缺乏力量或效力，也可作医学术语指勃起功能障碍；医学语境应保持客观尊重。',C('impotence.s1','政策分析','The review described the agency’s impotence in stopping the pollution as a lack of authority and effective tools.','评估将该机构无力制止污染归因于权限不足和缺少有效工具。','The review described the agency’s impotence / in stopping the pollution / as a lack of authority / and effective tools.','impotence 在此表示无力或无效；as 后解释这种无力的具体原因。','机构缺少有效手段，符合 s1。'),M('The review called the agency’s response impotence even though it had full authority and successfully stopped the pollution.','The review called the agency’s response effective because it stopped the pollution.','成功制止污染不体现无力或无效。'),[Q('impotence',1,1,'Political impotence is?','lack of power or effectiveness','complete control and success','a kind of policy implementation','s1 指缺乏力量或效力。'),Q('impotence',2,2,'In medical usage, impotence refers to?','difficulty achieving or maintaining an erection','a lack of authority in an agency','a rule introduced by government','s2 是医学术语，表述具体功能障碍。'),Q('impotence',3,1,'An agency’s impotence to stop pollution suggests it?','lacks effective power to stop it','has already stopped it successfully','is importing pollution','该语境表示机构无力制止。'),Q('impotence',4,2,'How should the medical sense be discussed?','factually and respectfully as a health condition','as a joke about a person','as a synonym for laziness','医学语境应客观且尊重地描述。')]);
P('impoverish','impoverish 可表示使人陷入贫困，也可指耗尽土壤肥力或削弱事物的质量。',C('impoverish.s2','土壤保护','Repeated heavy planting without restoring nutrients can impoverish the soil and reduce future harvests.','反复密集种植而不补充养分会使土壤变贫瘠，并降低未来收成。','Repeated heavy planting without restoring nutrients / can impoverish the soil / and reduce future harvests.','impoverish 在此表示使土壤失去肥力；can 表示可能产生的结果。','不补充养分会使土壤质量下降，符合 s2。'),M('The report said repeated nutrient loss impoverished the soil while making it richer and more fertile.','The report said nutrient loss depleted the soil and made it less fertile.','土壤肥力增加与 impoverish 的削弱义相反。'),[Q('impoverish',1,1,'To impoverish a family is to?','reduce it to poverty','make it wealthier','show it a grammar rule','s1 指使人贫困。'),Q('impoverish',2,2,'Repeated nutrient loss can impoverish?','the soil','an impostor','a religious hymn','s2 可指使土壤贫瘠。'),Q('impoverish',3,2,'A policy may impoverish a culture by?','weakening its richness or quality','helping it flourish','making it waterproof','impoverish 也可比喻削弱质量。'),Q('impoverish',4,1,'Which sentence uses the poverty sense?','The crisis impoverished many households.','The rain impoverished the soil.','The artist improvised a melody.','many households 成为陷入贫困的对象。')]);
P('impoverished','impoverished 是 impoverish 的过去分词形容词，表示非常贫困的。',C('impoverished.s1','社区援助','The clinic offers free evening appointments for impoverished families who cannot afford daytime care.','诊所为无力承担白天就诊费用的贫困家庭提供免费的晚间预约。','The clinic offers free evening appointments / for impoverished families / who cannot afford daytime care.','impoverished 修饰 families，描述经济贫困；who 从句说明其困难。','家庭无力负担常规服务，符合 s1。'),M('The article described a household with abundant savings and luxury homes as impoverished.','The article described the household as wealthy because it had abundant savings and luxury homes.','拥有大量存款和豪宅与贫困不符。'),[Q('impoverished',1,1,'An impoverished household is?','very poor','extremely wealthy','unable to be understood','impoverished 表示贫困的。'),Q('impoverished',2,1,'Why might a clinic offer free care to impoverished families?','they may be unable to afford usual fees','they have unlimited income','they own the clinic','贫困家庭可能无法承担常规费用。'),Q('impoverished',3,1,'Impoverished is related to the verb?','impoverish','impress','imply','impoverished 由 impoverish 派生。'),Q('impoverished',4,1,'Which evidence fits impoverished?','the family cannot afford basic services','the family owns several luxury homes','the family funds a large grant','无力承担基本服务与贫困相符。')]);
P('impractical','impractical 由否定前缀 im- 与 practical 构成，表示现实中难以实行、没有实际效用。',C('impractical.s1','通勤方案','A daily four-hour detour is impractical for most commuters, so the team looked for a closer park-and-ride site.','对大多数通勤者来说，每天绕行四小时并不现实，因此团队寻找更近的停车换乘点。','A daily four-hour detour / is impractical for most commuters / so the team looked for / a closer park-and-ride site.','impractical 作表语，表示实际难以操作；so 引出更可行的替代方案。','每天增加四小时绕行难以长期执行，符合 s1。'),M('The plan was called impractical even though it required no extra time, money, or equipment and worked easily.','The plan was practical because it required no extra resources and worked easily.','无需额外资源且容易执行的计划并不 impractical。'),[Q('impractical',1,1,'An impractical plan is?','not useful or workable in real life','easy to carry out in real conditions','a kind of foreign import','impractical 指不切实际。'),Q('impractical',2,1,'A four-hour daily detour may be impractical because it?','is difficult to sustain in everyday life','takes no time at all','guarantees a shorter commute','现实成本过高使其难以实行。'),Q('impractical',3,1,'The prefix im- in impractical means?','not','more than a hundred','together','im- 是否定前缀。'),Q('impractical',4,1,'A close opposite of impractical is?','workable','unrealistic','unusable','workable 表示可行。')]);
P('impracticality','impracticality 由 impractical 加名词后缀构成，指某想法在现实条件下无法奏效的性质。',C('impracticality.s1','场地规划','The impracticality of holding the event outdoors became clear when the only accessible path turned muddy after rain.','下雨后唯一的无障碍通道变得泥泞，这时在户外举办活动的不现实性就显现出来了。','The impracticality of holding the event outdoors / became clear / when the only accessible path / turned muddy after rain.','impracticality 是抽象名词，常用 the impracticality of doing 表示某方案行不通；when 引出原因。','场地条件让户外活动难以实施，符合 s1。'),M('The planners called the venue impracticality although it met every requirement and was easy to use.','The planners called the venue practical because it met every requirement and was easy to use.','满足全部要求且易用说明可行，不是不现实。'),[Q('impracticality',1,1,'Impracticality is the fact that an idea?','cannot work under real conditions','is certain to succeed','is only hinted at','impracticality 指不切实际、行不通。'),Q('impracticality',2,1,'What might reveal the impracticality of an outdoor venue?','its only accessible path becomes unusable after rain','it has enough shelter and dry paths','visitors arrive on time','实际限制暴露了方案难以操作。'),Q('impracticality',3,1,'Impracticality is the noun form related to?','impractical','impetuous','imperial','impracticality 由 impractical 派生。'),Q('impracticality',4,1,'Which phrase is natural?','the impracticality of the proposal','the impracticality to the proposed','an impracticality for proposes','常见结构为 impracticality of。')]);
P('imprecate','imprecate 源自拉丁语 imprecari（祈求），现代少见而正式，表示诅咒或祈求降祸。',C('imprecate.s1','古典戏剧','In the old tragedy, the betrayed ruler imprecated the army that had destroyed her city.','在这部古典悲剧中，遭背叛的统治者诅咒了摧毁她城池的军队。','In the old tragedy / the betrayed ruler imprecated the army / that had destroyed her city.','imprecate 是及物动词，后接被诅咒的对象；that 从句说明仇怨缘由。','角色祈求军队遭受伤害，符合 s1；该用法较少见、偏正式。'),M('The ruler imprecated the invading army by wishing them safety, peace, and a swift recovery.','The ruler blessed the invading army by wishing them safety, peace, and a swift recovery.','祝愿平安康复与祈求降祸意义相反。'),[Q('imprecate',1,1,'To imprecate someone is to?','curse them or pray that harm befall them','wish them safety and health','ask them to implement a policy','imprecate 指诅咒或祈求降祸。'),Q('imprecate',2,1,'Which scene fits imprecate?','a character calls for misfortune to fall on an enemy','a character offers a sincere blessing','a character makes a neutral observation','祈求敌人遭遇不幸符合该义。'),Q('imprecate',3,1,'Imprecate is best described as?','a rare, formal verb','a common adjective for practical plans','a noun for an imported product','这个词较少见且偏正式。'),Q('imprecate',4,1,'The closest contrast of imprecate is?','bless','curse','impose','bless 表示祝福，与诅咒相反。')]);
P('imprecise','imprecise 由否定前缀 im- 与 precise 构成，表示不准确或没有清楚界定。',C('imprecise.s1','科学记录','The first measurement was imprecise because the instrument’s scale could not show fractions of a millimeter.','第一次测量不够精确，因为仪器刻度无法显示毫米以下的小数。','The first measurement was imprecise / because the instrument’s scale / could not show fractions / of a millimeter.','imprecise 修饰 measurement，表示不够准确；because 指出仪器的精度限制。','刻度不能显示更细单位，测量结果就不够准确，符合 s1。'),M('The measurement was imprecise even though the calibrated instrument recorded the exact value to six decimal places.','The measurement was precise because a calibrated instrument recorded it to six decimal places.','校准仪器给出精确到六位小数的读数，不符合 imprecise。'),[Q('imprecise',1,1,'An imprecise measurement is?','not accurate enough','exact to every required detail','impossible to happen','imprecise 指不准确。'),Q('imprecise',2,1,'An imprecise instruction may?','leave its limits unclear','specify every boundary exactly','be a person who imports goods','该词也指界限表达不清。'),Q('imprecise',3,1,'Why was the measurement imprecise?','the scale could not show small fractions','the instrument was perfectly calibrated','the value was recorded exactly','仪器刻度精度不足导致不精确。'),Q('imprecise',4,1,'A close opposite of imprecise is?','accurate','vague','approximate','accurate 与 imprecise 相反。')]);
P('impregnate','impregnate 源自拉丁语 impregnare（使怀孕），也可表示使材料浸透或充满某种物质。',C('impregnate.s2','材料加工','The factory impregnates the canvas with a water-resistant coating before cutting it into outdoor covers.','工厂在把帆布裁成户外罩布前，先让防水涂层浸入材料。','The factory impregnates the canvas / with a water-resistant coating / before cutting it / into outdoor covers.','impregnate something with something 表示使材料浸透某物；before 说明加工顺序。','涂层渗入帆布，符合 s2。'),M('The manufacturer said it impregnated the canvas with coating but applied nothing and left the material untreated.','The manufacturer treated the canvas with a coating that soaked into the fibers.','没有施加任何物质就不能称为浸透处理。'),[Q('impregnate',1,1,'In its biological sense, impregnate means?','make a female animal or a woman pregnant','make a fabric waterproof','improve a measurement’s precision','s1 是使雌性动物或女性怀孕。'),Q('impregnate',2,2,'To impregnate fabric with resin is to?','soak or fill it with resin','remove every substance from it','measure it without touching it','s2 表示使材料浸透。'),Q('impregnate',3,2,'Which construction is natural?','impregnate the canvas with a coating','impregnate a coating from canvas','impregnate to the canvas a coating','常用结构是 impregnate something with something。'),Q('impregnate',4,1,'Which use fits the pregnancy sense?','a veterinary record states the animal became pregnant','a factory soaks cloth in resin','a researcher stains a paper sample','动物怀孕是该词的生物义。')]);
P('impress','impress 可表示使人钦佩、使人牢记重要性，也可指把标记压印到表面。',C('impress.s3','手工制作','The craft worker impressed the maker’s initials into the leather before stitching the cover.','手工艺人在缝合封面前，把制作者的姓名首字母压印在皮革上。','The craft worker impressed the maker’s initials / into the leather / before stitching the cover.','impress 在此表示把图案或文字压印在材料上；into 表示压入的表面。','首字母被压在皮革表面，符合 s3。'),M('The craft worker impressed the initials into the leather by leaving the surface completely blank and unmarked.','The craft worker left the leather blank instead of impressing initials into it.','表面完全没有标记就没有压印字母。'),[Q('impress',1,1,'To impress a visitor is to?','make them admire you','make them forget your name','send them an imported product','s1 指使人钦佩。'),Q('impress',2,2,'To impress the importance of safety on a team is to?','make them understand that it matters','hide the safety rule from them','press a logo into metal','s2 表示使人牢记重要性。'),Q('impress',3,3,'To impress a design into leather is to?','press the design onto its surface','describe it in a report','send the leather abroad','s3 指压印标记。'),Q('impress',4,1,'A skilled performance may impress an audience by?','earning their admiration','making the performance impossible','adding an import tax','出色表演会使观众钦佩。')]);
P('impression','impression 源自拉丁语 impressio（压入、印记），现代常指人对某事形成的感受或看法。',C('impression.s1','初次会面','My first impression of the new tutor was that she listened carefully and explained difficult ideas without rushing.','我对新导师的第一印象是她善于倾听，并且会从容地解释难懂的概念。','My first impression of the new tutor / was that she listened carefully / and explained difficult ideas / without rushing.','impression 常用 first impression of someone；that 从句说明形成的看法。','说话者形成了对导师的个人感受，符合 s1。'),M('My impression of the tutor was that I had never formed any opinion or feeling about her.','I had no impression of the tutor because I had not met or heard from her.','声称完全没有形成看法，与“我的印象是……”矛盾。'),[Q('impression',1,1,'An impression of a person is?','what you feel or think about them','a tax imposed by government','a tool used for a task','impression 指对某事的感受或看法。'),Q('impression',2,1,'A first impression is formed?','when you initially experience someone or something','only after a final court verdict','by importing a product','first impression 指初次形成的看法。'),Q('impression',3,1,'Which sentence uses impression naturally?','Her calm manner made a good impression on me.','I imposed an impression to the tax.','The impression imported the goods.','make an impression on 是常用搭配。'),Q('impression',4,1,'A positive impression means?','a favorable feeling or view','a negative measurement error','a rule that must be obeyed','positive 表示好的、正面的看法。')]);
P('impressionable','impressionable 由 impression 加 -able 构成，表示容易受他人或环境影响的。',C('impressionable.s1','媒介素养','Because younger readers can be impressionable, the workshop teaches them to check dramatic claims against reliable sources.','由于年纪较小的读者可能容易受影响，研习班教他们用可靠来源核实耸动说法。','Because younger readers can be impressionable / the workshop teaches them / to check dramatic claims / against reliable sources.','impressionable 描述容易受影响的特点；because 引出开展媒介教育的理由。','读者容易被夸张内容左右，符合 s1；句子聚焦培养核查能力。'),M('The report called the reader impressionable even though she evaluated every claim independently and ignored social pressure.','The report called the reader independent-minded because she evaluated claims for herself.','独立核查、无视压力不符合“容易受影响”。'),[Q('impressionable',1,1,'An impressionable person is?','easily shaped by other people or experiences','impossible to persuade under any circumstances','a person who imports goods','impressionable 指容易受影响。'),Q('impressionable',2,1,'Why teach young readers to verify dramatic claims?','they may be impressionable and need evaluation skills','they are unable to read','they already know every source is reliable','核查训练能帮助容易受影响的读者判断信息。'),Q('impressionable',3,1,'The suffix -able here suggests?','capable of being affected','a person who performs an action','a command','impressionable 表示能被印象塑造、容易受影响。'),Q('impressionable',4,1,'Which person is most impressionable in this sense?','someone readily influenced by a persuasive group','someone who weighs evidence independently','someone who has no opinions about art','容易被群体说服的人符合该义。')]);
P('impressionism','Impressionism 是十九世纪后期的艺术运动，重视光线、色彩和场景的即时观感。',C('impressionism.s1','艺术史课程','The exhibition introduces Impressionism through paintings that capture shifting light across gardens, rivers, and city streets.','展览通过捕捉花园、河流和城市街道上变化光线的绘画，介绍印象派艺术。','The exhibition introduces Impressionism / through paintings / that capture shifting light / across gardens, rivers, and city streets.','Impressionism 是艺术运动名称；through paintings 说明展览如何介绍该流派。','作品关注光线和场景的即时印象，符合 s1。'),M('The catalog labeled a movement Impressionism even though its works rejected light, color, and the immediate appearance of scenes.','The catalog described the movement as unrelated to Impressionism because it rejected those features.','拒绝光色及即时观感与词条概括的印象派特点不符。'),[Q('impressionism',1,1,'Impressionism is an art movement especially concerned with?','light, color, and the immediate look of a scene','the exact measurement of every object','only royal history','印象派重视光线、色彩和即时观感。'),Q('impressionism',2,1,'An Impressionist painting may capture?','changing light over a river','a legal rule’s implementation','a detailed shipping invoice','捕捉变化光线是典型主题。'),Q('impressionism',3,1,'Impressionism developed in the?','late nineteenth century','early medieval period only','distant future','词条给出十九世纪后期。'),Q('impressionism',4,1,'Which subject best fits Impressionism?','the fleeting appearance of a garden at dusk','a list of exact tax rates','an abstract grammar command','流动光线下的即时景象符合该流派。')]);
P('impressionist','impressionist 可指采用印象派画风的画家，也可指模仿名人声音和举止的表演者。',C('impressionist.s1','美术展览','The impressionist painted the harbor in quick strokes that emphasized the shifting colors of the water.','这位印象派画家用迅疾的笔触描绘港口，突出水面不断变化的色彩。','The impressionist painted the harbor / in quick strokes / that emphasized the shifting colors / of the water.','impressionist 在此指印象派画家；that 从句说明笔触呈现的效果。','作品通过色彩和笔触捕捉即时观感，符合 s1。'),M('The museum called the artist an impressionist but said she never painted and only repaired heating pipes.','The museum called the artist a hydronic technician because she repaired heating pipes.','只维修管道的人不是以印象派画作为业的画家。'),[Q('impressionist',1,1,'An impressionist in art is?','an artist who paints in the Impressionist manner','a person who imposes taxes','a visitor who forms an opinion','s1 指印象派画家。'),Q('impressionist',2,2,'An entertainer who copies a celebrity’s voice is an?','impressionist','impoverished person','importer','s2 指模仿名人的表演者。'),Q('impressionist',3,1,'Which work suggests an impressionist painter?','quick strokes capturing shifting light','a perfectly blank canvas','an exact list of measurements only','捕捉光色变化的绘画符合 s1。'),Q('impressionist',4,2,'A comedy impressionist may imitate a famous person’s?','voice and manner','tax record only','private thoughts exactly','表演者模仿名人的声音和举止。')]);
P('impressionistic','impressionistic 可指采用印象派风格，也可指仅凭总体感觉而非精确测量的。',C('impressionistic.s2','初步报告','The consultant gave an impressionistic overview of the market, noting broad patterns but not presenting measured sales data.','顾问给出了对市场的概括性印象描述，指出大致趋势，却没有提供测量过的销售数据。','The consultant gave an impressionistic overview of the market / noting broad patterns / but not presenting / measured sales data.','impressionistic 在此表示凭总体印象而非严谨测量；but 对比概括观察和数据证据。','报告呈现大致感受而无精确数据，符合 s2。'),M('The report was called impressionistic even though it was based on a complete audited dataset and exact measurements.','The report was called data-driven because it relied on audited figures and exact measurements.','严格依赖完整数据和精确测量并非“仅凭印象”。'),[Q('impressionistic',1,1,'An impressionistic painting is made?','in the manner of Impressionist art','as an exact technical diagram','as a tax document','s1 指印象派风格。'),Q('impressionistic',2,2,'An impressionistic report is based mainly on?','a general feeling rather than careful measurement','complete audited figures only','a command from a ruler','s2 指总体印象而非精确测量。'),Q('impressionistic',3,2,'Which report is impressionistic in sense 2?','one noting broad trends without measured sales figures','one listing audited values to the cent','one reproducing every survey response','没有精确数据而作概括判断符合 s2。'),Q('impressionistic',4,1,'A painter’s impressionistic approach emphasizes?','light and sensation over exact detail','legal implementation','careful accounting only','印象派画风突出光线和感受。')]);
P('impressive','impressive 由 impress 加 -ive 构成，形容因质量、技能或规模而令人钦佩、印象深刻的。',C('impressive.s1','音乐演出','The student gave an impressive recital, performing the difficult passage accurately after only a few weeks of practice.','这名学生的独奏演出令人赞叹，只练习了几周就准确演奏了那段困难乐句。','The student gave an impressive recital / performing the difficult passage accurately / after only a few weeks / of practice.','impressive 修饰 recital，说明演奏质量让人钦佩；after 引出练习时间。','短时间练习后准确演奏难段体现出色技能，符合 s1。'),M('The recital was called impressive even though the student stopped after one note and could not complete the piece.','The recital was called unfinished because the student could not complete the piece.','只演奏一个音符就停下难以体现令人钦佩的完成质量。'),[Q('impressive',1,1,'An impressive performance?','makes people admire its quality or skill','has no notable skill or effect','is difficult to understand only','impressive 指令人钦佩、印象深刻。'),Q('impressive',2,2,'An impressive building may be?','large and splendid enough to command respect','tiny and easy to overlook','a written implication','s2 指宏伟、威严的。'),Q('impressive',3,1,'Which achievement is impressive?','performing a difficult piece accurately after brief practice','stopping before beginning','forgetting every note','突出的技能表现令人钦佩。'),Q('impressive',4,1,'The closest synonym for impressive is?','remarkable','ordinary','improper','remarkable 表示值得注意、令人赞叹。')]);
P('impressively','impressively 是 impressive 的副词，表示达到令人钦佩的程度或方式。',C('impressively.s1','学习进展','The new reading program improved attendance impressively during its first term, according to the school’s published figures.','根据学校公布的数据，新阅读计划在第一个学期显著提高了出勤率。','The new reading program improved attendance impressively / during its first term / according to the school’s published figures.','impressively 修饰 improved，表示改善程度大、令人印象深刻；according to 指明数据来源。','出勤率提高明显且有数据支持，符合 s1。'),M('Attendance improved impressively by zero students, with no measurable or visible change.','Attendance did not improve because the number of students remained unchanged.','没有任何可测变化，就没有显著改善。'),[Q('impressively',1,1,'Impressively means?','so greatly or well that people are impressed','in a way no one notices','in an improper manner','impressively 表示令人钦佩地、程度显著地。'),Q('impressively',2,1,'If attendance rises impressively, it?','increases by a notable amount','stays exactly the same','falls without explanation','该副词强调变化幅度明显。'),Q('impressively',3,1,'In the example, what improved impressively?','attendance','the school’s building size','the reading program’s spelling','impressively 修饰 improved attendance。'),Q('impressively',4,1,'Impressively is related to the adjective?','impressive','impersonal','impossible','impressively 由 impressive 派生。')]);
P('imprint','imprint 与 press（压）相关，作动词表示把标记或图案压到某物表面。',C('imprint.s1','图书制作','The publisher will imprint the author’s name in gold on the cover before binding the special edition.','出版商将在装订特别版前，把作者姓名以金色压印在封面上。','The publisher will imprint the author’s name / in gold / on the cover / before binding the special edition.','imprint something on something 表示把标记压印在表面；before 引出工序顺序。','名字被压在封面上，符合 s1。'),M('The publisher said it imprinted the cover but left it entirely blank with no pressed mark.','The publisher left the cover blank instead of imprinting it.','没有压出任何标记就不是 imprint。'),[Q('imprint',1,1,'To imprint a name on a cover is to?','press the name onto its surface','read the name aloud','import the cover from abroad','imprint 指压印标记。'),Q('imprint',2,1,'Which construction is natural?','imprint a logo on the case','imprint a logo under to the case','imprint from a case the logo on','常用结构 imprint something on a surface。'),Q('imprint',3,1,'A maker’s mark imprinted in leather is?','pressed into the material','only described in speech','removed from the material','压在材料上的标记符合该义。'),Q('imprint',4,1,'The verb imprint is closest to?','stamp','erase','improvise','stamp 表示压印或盖印。')]);
P('imprison','imprison 由 prison 派生，可指依法关进监狱，也可指使人被困在无法逃离的地方。',C('imprison.s2','暴风雪救援','Heavy snow imprisoned the hikers in a mountain shelter until the rescue team cleared the pass.','大雪把徒步者困在山间避难所里，直到救援队清理出山口。','Heavy snow imprisoned the hikers / in a mountain shelter / until the rescue team / cleared the pass.','imprison 在此比喻使人受困、无法离开；until 表示受困状态何时结束。','积雪封住山口使徒步者无法离开，符合 s2。'),M('The snow imprisoned the hikers by leaving every route open and letting them walk away freely.','The snow trapped the hikers because it blocked every route out.','道路畅通、可以自由离开与受困相反。'),[Q('imprison',1,1,'To imprison someone legally is to?','put them in prison','invite them to a meeting','make them an importer','s1 指监禁。'),Q('imprison',2,2,'A storm can imprison people in a shelter by?','blocking every route out','opening every road','sending a message','s2 指使人无法逃离或离开。'),Q('imprison',3,1,'Which sentence uses the legal sense?','The court sentenced the thief to imprison him for the offense.','The storm imprisoned the hikers in a cabin.','The rule imprisoned an idea in a report.','依法关押对应 s1。'),Q('imprison',4,2,'If snow imprisons a group in a cabin, they?','cannot leave because routes are blocked','are serving a formal prison sentence','have chosen to leave immediately','封路使他们受困，符合 s2。')]);
P('imprisonment','imprisonment 由 imprison 加 -ment 构成，指被关押在监狱中的状态或惩罚。',C('imprisonment.s1','法律报道','The court considered the length of imprisonment only after reviewing the sentencing guidelines and the evidence.','法院在审阅量刑指南和证据后，才考虑监禁期限。','The court considered the length of imprisonment / only after reviewing / the sentencing guidelines / and the evidence.','imprisonment 是表示监禁状态或刑罚的名词；after 引出考虑刑期前的程序。','句中讨论被关押的期限，符合 s1。'),M('The report called the defendant’s imprisonment a period of complete freedom outside prison.','The report described the defendant’s imprisonment as time spent in prison.','监禁不是在监狱外完全自由。'),[Q('imprisonment',1,1,'Imprisonment is?','being kept in prison','a public celebration','the act of importing goods','imprisonment 指监禁。'),Q('imprisonment',2,1,'A sentence of five years’ imprisonment means?','five years in prison','five years of foreign trade','five years of artistic training','刑期表示在监狱关押的年限。'),Q('imprisonment',3,1,'Imprisonment is related to the verb?','imprison','impress','improve','imprisonment 由 imprison 派生。'),Q('imprisonment',4,1,'Which matter concerns imprisonment?','the length of a prison sentence','the color of a painting','a crop’s water needs','监禁期限属于该词范围。')]);
P('improbable','improbable 由否定前缀 im- 与 probable 构成，表示不大可能或奇怪得令人难信。',C('improbable.s1','天气预测','The forecast called snow on the tropical island improbable, though it did not rule out an unusual cold front.','天气预报认为这座热带岛屿降雪的可能性很低，但没有完全排除异常冷锋。','The forecast called snow on the tropical island improbable / though it did not rule out / an unusual cold front.','improbable 表示发生可能性低；though 说明低概率不等于绝无可能。','热带岛屿降雪很不可能但并非绝对不可能，符合 s1。'),M('The forecast described a sunrise tomorrow as improbable even though the sun rises there every day.','The forecast described a sunrise tomorrow as probable because it occurs there daily.','每天发生的日出并非不大可能。'),[Q('improbable',1,1,'An improbable event is?','unlikely to happen','certain to happen','a command from an authority','improbable 指不大可能。'),Q('improbable',2,1,'Snow on a tropical island may be called improbable because it?','is unlikely, though not necessarily impossible','happens there every day','has already been measured','低概率不等同完全不可能。'),Q('improbable',3,1,'The prefix im- in improbable means?','not','again and again','toward the sea','否定前缀构成“不大可能”。'),Q('improbable',4,1,'A close synonym of improbable is?','unlikely','inevitable','ordinary','unlikely 表示不太可能。')]);
P('impromptu','impromptu 源自拉丁语 in promptu（随时可用），可作形容词、副词或名词，表示未经准备的即兴表达。',C('impromptu.s1','社区活动','When the scheduled speaker was delayed, Asha gave an impromptu welcome while the organizers rearranged the program.','原定演讲者迟到时，阿莎即兴致欢迎辞，组织者则重新安排节目。','When the scheduled speaker was delayed / Asha gave an impromptu welcome / while the organizers / rearranged the program.','impromptu 在此作形容词修饰 welcome，表示事先没有计划；when 引出临时状况。','她临时上台致辞，符合 s1。'),M('Asha’s impromptu speech had been rehearsed word for word for weeks and scheduled months ahead.','Asha’s planned speech had been rehearsed and scheduled in advance.','预先安排并排练多周的演讲不是即兴的。'),[Q('impromptu',1,1,'An impromptu speech is?','given without being planned beforehand','carefully scripted months in advance','impossible to deliver','s1 表示未经准备、即兴的。'),Q('impromptu',2,2,'If a band plays impromptu, it plays?','without preparation','only from a printed score','with no sound at all','s2 是副词义“即兴地”。'),Q('impromptu',3,3,'An impromptu can also be?','a piece performed or made without preparation','a prison sentence','a measure of importance','s3 可作即兴作品或表演。'),Q('impromptu',4,1,'Why was Asha’s welcome impromptu?','the scheduled speaker was delayed','she had rehearsed it for months','the event had no program','临时情况促使她即席发言。')]);
P('improper','improper 由否定前缀 im- 与 proper 构成，表示不合适、不正当或不符合规范的。',C('improper.s1','实验室规范','It would be improper to publish the participant’s medical details without permission, even if the data seem useful.','即使这些数据似乎有用，未经许可公布参与者的医疗细节也不合适。','It would be improper to publish the participant’s medical details / without permission / even if the data / seem useful.','improper 修饰发布行为，表示不恰当；even if 表示数据有用也不能改变规范要求。','未经许可公开敏感资料不合适，符合 s1。'),M('The editor called it improper to protect participants’ privacy and follow the consent agreement.','The editor called it proper to protect participants’ privacy and follow the consent agreement.','保护隐私并遵守同意协议是适当做法。'),[Q('improper',1,1,'An improper action is?','not right or appropriate','fully correct and suitable','a sudden urge','improper 表示不适当。'),Q('improper',2,1,'Publishing private data without consent may be?','improper','impressive','impartial','未经许可披露资料不合适。'),Q('improper',3,1,'The prefix im- in improper expresses?','negation','a hundredfold amount','a person who performs an act','im- 是否定前缀。'),Q('improper',4,1,'A close opposite of improper is?','appropriate','wrong','unsuitable','appropriate 表示合适。')]);
P('impropriety','impropriety 来自 improper 相关词形，指违反公认诚实或礼貌规范的行为或品质。',C('impropriety.s1','公共事务','The review found an impropriety in the official’s undisclosed gift arrangement and recommended a transparent ethics check.','审查发现这名官员未披露的收礼安排存在不当行为，并建议进行透明的伦理核查。','The review found an impropriety / in the official’s undisclosed gift arrangement / and recommended / a transparent ethics check.','impropriety 是表示不当行为的名词；in 指问题所在，and 连接审查建议。','未披露礼物安排违反透明规范，符合 s1。'),M('The panel called the official’s fully disclosed and policy-compliant conduct an impropriety.','The panel called the official’s conduct proper because it was disclosed and followed policy.','公开披露并遵守规定的行为不属于不正当。'),[Q('impropriety',1,1,'An impropriety is?','an act or behavior against accepted standards','a harmless weather change','a process for importing goods','impropriety 指不当或不正行为。'),Q('impropriety',2,1,'An undisclosed gift to an official may raise a concern about?','impropriety','impressionism','impracticality','未披露的利益安排可能违反规范。'),Q('impropriety',3,1,'Impropriety is related to the adjective?','improper','improbable','impressive','impropriety 和 improper 同词族。'),Q('impropriety',4,1,'Which behavior may be an impropriety?','concealing a conflict of interest','following a transparent ethics rule','declaring a gift as required','隐瞒利益冲突可能违反诚实规范。')]);
P('improve','improve 可表示使某物变好、情况自行好转、增值，也可表示在已有成果上做得更好。',C('improve.s2','康复记录','After several weeks of rest and therapy, Mei’s shoulder began to improve and she could lift her arm more comfortably.','经过几周休息和治疗后，梅的肩膀开始好转，她抬手也更舒服了。','After several weeks of rest and therapy / Mei’s shoulder began to improve / and she could lift her arm / more comfortably.','improve 在此是不及物动词，表示状况变好；began to 表示好转开始出现。','肩部状况自行改善，符合 s2。'),M('The patient’s shoulder improved by becoming more painful and less mobile each week.','The patient’s shoulder worsened as pain increased and movement decreased.','疼痛加重、活动受限是恶化而不是好转。'),[Q('improve',1,1,'To improve a system is to?','make it better','make it less useful','describe it without change','s1 指改善某物。'),Q('improve',2,2,'If someone’s health improves, it?','becomes better','is made worse by treatment','is imported from abroad','s2 指情况好转。'),Q('improve',3,3,'A property may improve in value when it?','becomes more valuable','loses all value','is imprisoned','s3 指增值。'),Q('improve',4,4,'To improve on a previous design is to?','produce something better than before','copy it without change','make it impossible to use','s4 表示超过、做得更好。')]);
P('improvement','improvement 由 improve 加 -ment 构成，指使事物变好的行为、过程或结果。',C('improvement.s1','服务反馈','The clinic made a clear improvement to its appointment system by adding evening hours for working patients.','诊所增加了面向上班患者的晚间时段，预约系统因此有了明显改进。','The clinic made a clear improvement to its appointment system / by adding evening hours / for working patients.','improvement to 表示对系统的改进；by 引出改进采取的措施。','新增服务使预约系统更加便利，符合 s1。'),M('The clinic described a longer wait and fewer appointment options as an improvement to the service.','The clinic described longer waits and fewer options as a decline in service.','等待更久、选项更少通常是服务变差而非改进。'),[Q('improvement',1,1,'An improvement is?','a change or action that makes something better','a change that always makes things worse','a person pretending to be someone else','improvement 指改进。'),Q('improvement',2,1,'Evening appointments may be an improvement because they?','make the service more accessible','reduce all access','make a plan impossible','晚间时段让上班患者更容易就诊。'),Q('improvement',3,1,'Which phrase is natural?','an improvement to the system','an improvement under a system of','improvement the system to','常用结构 an improvement to。'),Q('improvement',4,1,'Improvement is the noun related to?','improve','imprison','imprecate','improvement 由 improve 派生。')]);
P('improvident','improvident 源于拉丁语 provident（预见、预作准备）并带否定前缀 im-，形容不为未来储备或筹划的。',C('improvident.s1','家庭预算','Buying expensive equipment with the entire emergency fund was improvident because no savings remained for unexpected bills.','把全部应急储蓄用来购买昂贵设备是不明智的，因为遇到意外账单时已没有存款。','Buying expensive equipment with the entire emergency fund / was improvident / because no savings remained / for unexpected bills.','improvident 作表语形容词，评价行为缺乏未来准备；because 说明风险所在。','花光应急储蓄、未顾及未来开支，符合 s1。'),M('The report called the purchase improvident even though it preserved ample savings for future emergencies.','The report called the purchase prudent because it left ample savings for future emergencies.','保留充足应急储蓄体现有远见，不是 improvident。'),[Q('improvident',1,1,'An improvident person?','fails to save or prepare for future needs','carefully plans for future costs','is easy to influence','improvident 指无远见、不为未来准备。'),Q('improvident',2,1,'Spending the entire emergency fund on a luxury item may be?','improvident','impressive','impermeable','没有为未来突发开支留准备可能不明智。'),Q('improvident',3,1,'The prefix im- in improvident means?','not','very much','again','im- 是否定意义。'),Q('improvident',4,1,'A close opposite of improvident is?','prudent','wasteful','short-sighted','prudent 表示谨慎、有远见。')]);
P('improvisation','improvisation 由 improvise 加 -ation 构成，指在现场临时编造或即兴表演。',C('improvisation.s1','现场音乐','When the amplifier failed, the musicians used a brief improvisation to keep the audience engaged while it was repaired.','扩音器故障时，乐手临时即兴演奏了一小段，让观众在维修期间仍有内容可听。','When the amplifier failed / the musicians used a brief improvisation / to keep the audience engaged / while it was repaired.','improvisation 是名词，指即兴创作或表演；when 与 while 交代临时状况。','乐手没有固定曲目而现场编奏，符合 s1。'),M('The musicians called the piece an improvisation even though they performed a fully scripted recording without changing anything.','The musicians called the piece a fixed arrangement because it was fully scripted.','照着预先固定的录音一成不变地演奏不是即兴创作。'),[Q('improvisation',1,1,'An improvisation is?','something made up on the spot','a prison sentence','a carefully measured import tax','improvisation 指即兴创作。'),Q('improvisation',2,1,'Why did the band improvise during the repair?','to fill the unexpected gap with live music','to play a recording exactly as planned','to increase the amplifier’s weight','临时演奏填补了维修空档。'),Q('improvisation',3,1,'Improvisation is the noun form related to?','improvise','impoverish','impose','improvisation 和 improvise 同词族。'),Q('improvisation',4,1,'Which performance is an improvisation?','a tune invented as it is played','a recording repeated without change','a rehearsed script read word for word','现场创编的乐曲属于即兴。')]);
P('improvise','improvise 来自意为“未预见”的拉丁语 improvisus 相关词形，表示没有预先准备而现场创作或应变。',C('improvise.s1','紧急活动','When the microphone stopped working, the presenter improvised by moving closer to the audience and speaking without slides.','麦克风停止工作后，主持人临场应变，走近观众并脱稿讲话。','When the microphone stopped working / the presenter improvised / by moving closer to the audience / and speaking without slides.','improvise 表示现场临时想办法；by 引出具体应变方式。','主持人没有原定设备和幻灯片而当场调整，符合 s1。'),M('The presenter improvised by following a complete script written and rehearsed for that exact equipment failure months earlier.','The presenter followed a prepared contingency script rather than improvising.','专为故障提前写好并排练的脚本不是现场临时编出的。'),[Q('improvise',1,1,'To improvise is to?','make something up or adapt on the spot','follow a fixed plan without change','impose a tax','improvise 指即兴创作或临场应变。'),Q('improvise',2,1,'The presenter improvised after the microphone failed by?','changing the delivery in the moment','ending the event exactly as scripted','waiting for the amplifier to become a person','临场改变讲话方式是应变。'),Q('improvise',3,1,'Which musician is improvising?','one inventing a melody while performing','one playing a recording note for note','one tuning a silent guitar only','现场编出旋律属于即兴。'),Q('improvise',4,1,'Improvise is related to the noun?','improvisation','impropriety','impression','improvisation 是其名词形式。')]);
P('improviser','improviser 由 improvise 加 -er 构成，指不依赖固定剧本或乐谱而现场创作的人。',C('improviser.s1','即兴喜剧','The improviser listened to the audience’s suggestion and built a short scene around a lost umbrella.','这位即兴表演者听取观众的建议，围绕一把丢失的雨伞创作了一段短场景。','The improviser listened to the audience’s suggestion / and built a short scene / around a lost umbrella.','improviser 指即兴创作的人；and 连接倾听建议与现场编场景。','表演者根据观众建议临时创作，符合 s1。'),M('The performer was called an improviser even though she only read a fixed script and could not create anything spontaneously.','The performer was called a scripted actor because she only read a fixed script.','只照固定剧本朗读不体现即兴创作。'),[Q('improviser',1,1,'An improviser creates?','without a fixed script or score','only from an exact fixed script','a new tax rule','improviser 指即兴创作者或表演者。'),Q('improviser',2,1,'A comedy improviser may use?','a suggestion from the audience','a fully fixed scene that cannot change','an imported machine','现场表演者可根据观众建议创作。'),Q('improviser',3,1,'The suffix -er identifies?','a person who performs an action','a condition of being unable','a past event only','-er 表示从事 improvise 的人。'),Q('improviser',4,1,'Which musician is an improviser?','one creating a melody live without a set score','one playing a recording only','one printing sheet music','现场无固定乐谱创作符合定义。')]);
P('imprudent','imprudent 由否定前缀 im- 与 prudent 构成，表示面对风险时判断不佳、不谨慎。',C('imprudent.s1','旅行准备','It would be imprudent to hike the exposed ridge without checking the weather or carrying warm layers.','不查看天气、也不带保暖衣物就徒步走暴露的山脊是不谨慎的。','It would be imprudent to hike the exposed ridge / without checking the weather / or carrying warm layers.','imprudent 修饰 hiking 这一选择，表示未妥善判断风险；without 并列两项缺少的准备。','忽略天气与保暖准备会增加风险，符合 s1。'),M('The ranger called the hike imprudent even though the group checked the forecast, carried safety gear, and chose a safe route.','The ranger called the hike prudent because the group checked conditions and carried safety gear.','充分评估风险并做好准备不符合 imprudent。'),[Q('imprudent',1,1,'An imprudent decision shows?','poor judgment about risk','careful thought and preparation','a religious song','imprudent 指轻率、不谨慎。'),Q('imprudent',2,1,'Which choice is imprudent?','hiking an exposed ridge without checking weather or gear','checking the forecast and carrying warm clothing','postponing a trip during a storm warning','未查天气且无装备会忽视风险。'),Q('imprudent',3,1,'The prefix im- in imprudent means?','not','more than','between','im- 是否定前缀。'),Q('imprudent',4,1,'A close opposite of imprudent is?','wise and cautious','rash','reckless','谨慎与 imprudent 相反。')]);
P('impudence','impudence 源自拉丁语 impudentia，指大胆无礼、厚颜无耻的行为或态度。',C('impudence.s1','礼貌争论','The chair was surprised by the impudence of interrupting the guest speaker to mock her accent.','有人打断嘉宾演讲并嘲笑她的口音，这种厚颜无礼让主持人很惊讶。','The chair was surprised / by the impudence of interrupting the guest speaker / to mock her accent.','impudence 是名词，表示大胆无礼；of + 动名词说明无礼行为的具体内容。','打断演讲并嘲笑他人明显欠缺尊重，符合 s1。'),M('The chair praised the impudence of waiting politely until the speaker finished and then asking a respectful question.','The chair praised the courtesy of waiting politely and asking a respectful question.','耐心等候并礼貌提问是有礼貌，不是厚颜无礼。'),[Q('impudence',1,1,'Impudence is?','bold rudeness','careful courtesy','a lack of water in the soil','impudence 指厚颜无礼。'),Q('impudence',2,1,'Which action shows impudence?','interrupting a guest to mock her accent','waiting until she finishes and asking politely','thanking her for the talk','嘲弄并打断嘉宾表现出无礼。'),Q('impudence',3,1,'The word impudence names?','a quality or act','a person who imports goods','a formal command','impudence 是描述态度或行为的名词。'),Q('impudence',4,1,'A close opposite of impudence is?','respectfulness','shameless rudeness','impropriety','尊重有礼与 impudence 相反。')]);
P('impudent','impudent 由拉丁语 impudens 传入英语，形容厚颜无礼、毫不尊重他人的。',C('impudent.s1','课堂互动','The student made an impudent remark about the visiting scientist, then apologized when the teacher explained why it was disrespectful.','学生对来访科学家说了句无礼的话，老师解释其不尊重后，他便道了歉。','The student made an impudent remark / about the visiting scientist / then apologized / when the teacher explained why it was disrespectful.','impudent 修饰 remark，表示无礼；then 与 when 展示道歉发生的前后关系。','言语冒犯来访者、缺少尊重，符合 s1。'),M('The teacher described the student’s impudent remark as respectful because it honored the scientist and avoided mockery.','The teacher described the student’s remark as respectful because it honored the scientist.','尊重并赞扬科学家的言论不符合 impudent。'),[Q('impudent',1,1,'An impudent remark is?','shamelessly disrespectful','carefully deferential','a scientific measurement','impudent 指放肆、无礼。'),Q('impudent',2,1,'Which behavior is impudent?','mocking a guest speaker to their face','listening quietly and thanking them','asking a relevant question politely','当面嘲弄来宾缺少尊重。'),Q('impudent',3,1,'Impudent is an?','adjective','abstract noun for a tax','adverb meaning without preparation','impudent 是形容词。'),Q('impudent',4,1,'A close synonym for impudent is?','insolent','respectful','careful','insolent 表示傲慢无礼。')]);
P('impulse','impulse 可指突发的强烈欲望、推动事物发展的力量、电或神经信号，也可指物理中的冲量。',C('impulse.s1','消费选择','On impulse, Leila bought the bright scarf at the market before considering whether it matched anything she owned.','莱拉一时冲动，在考虑它是否搭配自己的衣物前就买下了集市上的亮色围巾。','On impulse / Leila bought the bright scarf at the market / before considering / whether it matched anything she owned.','on impulse 是固定短语，表示凭一时冲动；before 引出她没有先考虑的事情。','未经计划便突然购买体现 s1。'),M('Leila bought the scarf on impulse after comparing every option for several months and following a detailed plan.','Leila bought the scarf after careful planning rather than on impulse.','数月比较并按计划购买不是突发冲动。'),[Q('impulse',1,1,'An impulse purchase is made because of?','a sudden strong urge','a long formal process','a water-resistant surface','s1 指突发的强烈念头。'),Q('impulse',2,2,'A force giving impetus to a project can be an?','impulse','impostor','impropriety','s2 指推动发展的力量。'),Q('impulse',3,3,'A brief nerve impulse is?','an electrical or nerve signal','a tax brought into a country','a painting style','s3 指短暂电或神经信号。'),Q('impulse',4,4,'In physics, impulse equals?','force multiplied by the time it acts','mass divided by color','speed without time','s4 是力与作用时间的乘积。')]);
P('impulsive','impulsive 由 impulse 加 -ive 构成，形容行动前没有充分思考的、冲动的。',C('impulsive.s1','日常决策','An impulsive decision to quit by text left Nora without a transition plan, so she later arranged a meeting to discuss next steps.','诺拉冲动地发短信辞职，却没有过渡计划，因此后来安排了一次会议讨论下一步。','An impulsive decision to quit by text / left Nora without a transition plan / so she later arranged a meeting / to discuss next steps.','impulsive 修饰 decision，表示未深思的冲动决定；so 引出事后补救。','发短信辞职而未作安排体现行动前缺少考虑，符合 s1。'),M('The decision was impulsive even though Nora compared options for months, consulted mentors, and made a detailed transition plan.','The decision was considered because Nora reviewed her options and planned the transition.','长期比较、咨询和制定计划并非未加思考的冲动行动。'),[Q('impulsive',1,1,'An impulsive person acts?','without thinking carefully first','only after a long review','according to a fixed law','impulsive 表示行动前没有仔细思考。'),Q('impulsive',2,1,'Which choice is impulsive?','quitting suddenly by text without a plan','reviewing options and arranging a transition','waiting until a decision is well considered','突然行动且无计划符合该义。'),Q('impulsive',3,1,'Impulsive is related to the noun?','impulse','importance','imposition','impulsive 由 impulse 派生。'),Q('impulsive',4,1,'The closest opposite of impulsive is?','deliberate','rash','hasty','deliberate 表示经过思考的。')]);

})();
